Table Partitioning -- Range partitioning by date (PostgreSQL declarative partitioning)
CREATE TABLE orders (
    order_id    BIGSERIAL,
    customer_id BIGINT NOT NULL,
    order_date  DATE NOT NULL,
    total_amount DECIMAL(10,2),
    status      VARCHAR(20),
    PRIMARY KEY (order_id, order_date)
) PARTITION BY RANGE (order_date);

-- Create quarterly partitions
CREATE TABLE orders_2024_q1 PARTITION OF orders
    FOR VALUES FROM ('2024-01-01') TO ('2024-04-01');
CREATE TABLE orders_2024_q2 PARTITION OF orders
    FOR VALUES FROM ('2024-04-01') TO ('2024-07-01');
CREATE TABLE orders_2024_q3 PARTITION OF orders
    FOR VALUES FROM ('2024-07-01') TO ('2024-10-01');
CREATE TABLE orders_2024_q4 PARTITION OF orders
    FOR VALUES FROM ('2024-10-01') TO ('2025-01-01');
CREATE TABLE orders_default PARTITION OF orders DEFAULT;

-- Hash partitioning for even distribution across shards
CREATE TABLE audit_logs (
    log_id      BIGSERIAL,
    user_id     BIGINT NOT NULL,
    action      VARCHAR(50),
    created_at  TIMESTAMP DEFAULT NOW(),
    PRIMARY KEY (log_id, user_id)
) PARTITION BY HASH (user_id);

CREATE TABLE audit_logs_p0 PARTITION OF audit_logs
    FOR VALUES WITH (MODULUS 4, REMAINDER 0);
CREATE TABLE audit_logs_p1 PARTITION OF audit_logs
    FOR VALUES WITH (MODULUS 4, REMAINDER 1);
CREATE TABLE audit_logs_p2 PARTITION OF audit_logs
    FOR VALUES WITH (MODULUS 4, REMAINDER 2);
CREATE TABLE audit_logs_p3 PARTITION OF audit_logs
    FOR VALUES WITH (MODULUS 4, REMAINDER 3);

-- Automate partition creation for future months
CREATE OR REPLACE FUNCTION create_monthly_partition()
RETURNS void AS $$
DECLARE
    partition_date DATE := date_trunc('month', NOW() + interval '1 month');
    partition_name TEXT;
    start_date TEXT;
    end_date TEXT;
BEGIN
    partition_name := 'orders_' || to_char(partition_date, 'YYYY_MM');
    start_date := to_char(partition_date, 'YYYY-MM-DD');
    end_date := to_char(partition_date + interval '1 month', 'YYYY-MM-DD');

    EXECUTE format(
        'CREATE TABLE IF NOT EXISTS %I PARTITION OF orders FOR VALUES FROM (%L) TO (%L)',
        partition_name, start_date, end_date
    );
END;
$$ LANGUAGE plpgsql;

Query Optimization Techniques -- Replace correlated subquery with JOIN + aggregation
-- BEFORE: executes subquery once per row in outer query
SELECT c.name, c.email,
    (SELECT COUNT(*) FROM orders o WHERE o.customer_id = c.customer_id) AS order_count
FROM customers c WHERE c.region = 'US';

-- AFTER: single pass with LEFT JOIN
SELECT c.name, c.email, COALESCE(o.order_count, 0) AS order_count
FROM customers c
LEFT JOIN (
    SELECT customer_id, COUNT(*) AS order_count
    FROM orders GROUP BY customer_id
) o ON o.customer_id = c.customer_id
WHERE c.region = 'US';

-- Keyset pagination instead of OFFSET for large datasets
-- BEFORE: OFFSET scans and discards rows (O(offset) per page)
SELECT * FROM orders ORDER BY order_date DESC, order_id DESC
OFFSET 100000 LIMIT 50;

-- AFTER: keyset pagination uses index efficiently (O(1) per page)
SELECT * FROM orders
WHERE (order_date, order_id) < ('2024-03-15', 987654)
ORDER BY order_date DESC, order_id DESC
LIMIT 50;

-- Batch processing to avoid long-running locks
DO $$
DECLARE
    batch_size INT := 5000;
    rows_affected INT;
BEGIN
    LOOP
        WITH batch AS (
            SELECT order_id FROM orders
            WHERE order_date < '2023-01-01' AND status != 'ARCHIVED'
            LIMIT batch_size
            FOR UPDATE SKIP LOCKED
        )
        UPDATE orders SET status = 'ARCHIVED'
        WHERE order_id IN (SELECT order_id FROM batch);

        GET DIAGNOSTICS rows_affected = ROW_COUNT;
        COMMIT;
        EXIT WHEN rows_affected = 0;
        PERFORM pg_sleep(0.1);
    END LOOP;
END $$;

-- Use materialized views for expensive aggregations
CREATE MATERIALIZED VIEW daily_revenue AS
SELECT date_trunc('day', order_date) AS day,
       COUNT(*) AS order_count,
       SUM(total_amount) AS revenue,
       AVG(total_amount) AS avg_order_value
FROM orders
WHERE status = 'completed'
GROUP BY date_trunc('day', order_date);

CREATE UNIQUE INDEX idx_daily_revenue_day ON daily_revenue (day);

-- Refresh concurrently (no lock on reads during refresh)
REFRESH MATERIALIZED VIEW CONCURRENTLY daily_revenue;

Transaction Isolation Levels -- Demonstrate Read Committed vs Repeatable Read behavior
-- Session 1: Read Committed (PostgreSQL default)
BEGIN TRANSACTION ISOLATION LEVEL READ COMMITTED;
SELECT balance FROM accounts WHERE account_id = 'A001';  -- Returns 1000

-- Meanwhile, Session 2 commits: UPDATE accounts SET balance = 500 WHERE account_id = 'A001';

SELECT balance FROM accounts WHERE account_id = 'A001';  -- Returns 500 (sees committed change)
COMMIT;

-- Session 1: Repeatable Read
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ;
SELECT balance FROM accounts WHERE account_id = 'A001';  -- Returns 1000

-- Meanwhile, Session 2 commits: UPDATE accounts SET balance = 500 WHERE account_id = 'A001';

SELECT balance FROM accounts WHERE account_id = 'A001';  -- Still returns 1000 (snapshot isolation)
-- If we try to UPDATE the same row, we get a serialization failure:
UPDATE accounts SET balance = balance - 100 WHERE account_id = 'A001';
-- ERROR: could not serialize access due to concurrent update
ROLLBACK;

-- Serializable isolation: prevents phantom reads and write skew
BEGIN TRANSACTION ISOLATION LEVEL SERIALIZABLE;
SELECT SUM(balance) FROM accounts WHERE owner_id = 'user-1';  -- Returns 2000
-- Business rule: total balance across all accounts must stay >= 1000
UPDATE accounts SET balance = balance - 800 WHERE account_id = 'A001';
COMMIT;  -- May fail with serialization error if concurrent transaction also modified these accounts

Optimistic Concurrency Control // JPA entity with version field for optimistic locking
@Entity
@Table(name = "products")
public class Product {
    @Id
    private UUID id;

    private String name;
    private BigDecimal price;
    private int stockQuantity;

    @Version  // JPA manages this automatically
    private long version;

    public void decrementStock(int quantity) {
        if (this.stockQuantity < quantity) {
            throw new InsufficientStockException(this.id, quantity, this.stockQuantity);
        }
        this.stockQuantity -= quantity;
    }
}

// Service layer with retry on optimistic lock failure
@Service
@RequiredArgsConstructor
public class InventoryService {

    private final ProductRepository productRepository;

    @Retryable(
        retryFor = OptimisticLockingFailureException.class,
        maxAttempts = 3,
        backoff = @Backoff(delay = 100, multiplier = 2)
    )
    @Transactional
    public void reserveStock(UUID productId, int quantity) {
        Product product = productRepository.findById(productId)
            .orElseThrow(() -> new ProductNotFoundException(productId));

        product.decrementStock(quantity);
        productRepository.save(product);
        // If another transaction modified this product since we read it,
        // JPA throws OptimisticLockingFailureException and @Retryable retries
    }
}

