Pessimistic Locking -- SELECT FOR UPDATE acquires a row-level exclusive lock
-- Other transactions attempting to lock the same rows will block until this transaction completes
BEGIN;
SELECT * FROM seats
WHERE flight_id = 'FL-123' AND seat_number = '14A' AND status = 'available'
FOR UPDATE;

-- If the row exists and is available, we have an exclusive lock
UPDATE seats SET status = 'reserved', reserved_by = 'user-456', reserved_at = NOW()
WHERE flight_id = 'FL-123' AND seat_number = '14A';
COMMIT;

-- SKIP LOCKED: non-blocking alternative for work queue patterns
-- Each worker picks up unprocessed tasks without blocking on locked rows
BEGIN;
SELECT task_id, payload FROM task_queue
WHERE status = 'pending'
ORDER BY priority DESC, created_at ASC
LIMIT 10
FOR UPDATE SKIP LOCKED;

UPDATE task_queue SET status = 'processing', worker_id = 'worker-3', started_at = NOW()
WHERE task_id IN (...selected task IDs...);
COMMIT;

-- NOWAIT: fail immediately if lock cannot be acquired
BEGIN;
SELECT * FROM accounts WHERE account_id = 'A001' FOR UPDATE NOWAIT;
-- If another transaction holds the lock: ERROR: could not obtain lock on row
-- Application can immediately return "resource busy" to the user

Distributed Saga Pattern // Saga orchestrator for order processing across multiple services
@Service
@RequiredArgsConstructor
public class OrderSagaOrchestrator {

    private final PaymentService paymentService;
    private final InventoryService inventoryService;
    private final ShippingService shippingService;
    private final OrderRepository orderRepository;

    @Transactional
    public OrderResult processOrder(Order order) {
        SagaContext context = new SagaContext(order.getId());

        try {
            // Step 1: Reserve inventory
            InventoryReservation reservation = inventoryService.reserve(order.getItems());
            context.addCompensation(() -> inventoryService.release(reservation.getId()));

            // Step 2: Process payment
            PaymentResult payment = paymentService.charge(order.getPaymentDetails());
            context.addCompensation(() -> paymentService.refund(payment.getId()));

            // Step 3: Schedule shipping
            ShipmentResult shipment = shippingService.schedule(order.getShippingDetails());
            context.addCompensation(() -> shippingService.cancel(shipment.getId()));

            // All steps succeeded
            order.setStatus(OrderStatus.CONFIRMED);
            orderRepository.save(order);
            return OrderResult.success(order);

        } catch (Exception e) {
            // Execute compensating transactions in reverse order
            context.compensate();
            order.setStatus(OrderStatus.FAILED);
            order.setFailureReason(e.getMessage());
            orderRepository.save(order);
            return OrderResult.failure(order, e);
        }
    }
}

// Choreography-based saga with events
@Component
@RequiredArgsConstructor
public class PaymentEventHandler {

    private final OrderRepository orderRepository;
    private final EventPublisher eventPublisher;

    @EventListener
    @Transactional
    public void handlePaymentCompleted(PaymentCompletedEvent event) {
        Order order = orderRepository.findById(event.getOrderId())
            .orElseThrow();
        order.markPaymentReceived(event.getPaymentId());
        orderRepository.save(order);
        eventPublisher.publish(new OrderReadyForShipmentEvent(order.getId()));
    }

    @EventListener
    @Transactional
    public void handlePaymentFailed(PaymentFailedEvent event) {
        Order order = orderRepository.findById(event.getOrderId())
            .orElseThrow();
        order.markPaymentFailed(event.getReason());
        orderRepository.save(order);
        // Publish compensation event
        eventPublisher.publish(new ReleaseInventoryEvent(order.getId()));
    }
}

Eventual Consistency with Outbox Pattern -- Outbox table ensures atomicity between local state change and event publishing
CREATE TABLE outbox_events (
    event_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    aggregate_type VARCHAR(100) NOT NULL,
    aggregate_id UUID NOT NULL,
    event_type VARCHAR(100) NOT NULL,
    payload JSONB NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    published_at TIMESTAMP WITH TIME ZONE,  -- NULL until published
    retry_count INTEGER DEFAULT 0
);

CREATE INDEX idx_outbox_unpublished ON outbox_events (created_at)
    WHERE published_at IS NULL; // Transactional outbox: write event in same transaction as state change
@Service
@RequiredArgsConstructor
public class OrderService {

    private final OrderRepository orderRepository;
    private final OutboxRepository outboxRepository;

    @Transactional  // Both writes in same transaction = atomic
    public Order createOrder(CreateOrderRequest request) {
        Order order = Order.from(request);
        order = orderRepository.save(order);

        // Write event to outbox table (same transaction)
        OutboxEvent event = OutboxEvent.builder()
            .aggregateType("Order")
            .aggregateId(order.getId())
            .eventType("OrderCreated")
            .payload(objectMapper.writeValueAsString(new OrderCreatedPayload(order)))
            .build();
        outboxRepository.save(event);

        return order;
    }
}

// Separate publisher polls outbox and publishes to message broker
@Scheduled(fixedDelay = 1000)
@Transactional
public void publishOutboxEvents() {
    List<OutboxEvent> events = outboxRepository.findUnpublished(100);
    for (OutboxEvent event : events) {
        try {
            kafkaTemplate.send(event.getEventType(), event.getAggregateId().toString(),
                event.getPayload());
            event.markPublished();
        } catch (Exception e) {
            event.incrementRetryCount();
            if (event.getRetryCount() > MAX_RETRIES) {
                event.markFailed();
                alertService.notify("Outbox event failed: " + event.getEventId());
            }
        }
    }
    outboxRepository.saveAll(events);
}

List Implementations and Operations // ArrayList: best for random access and iteration
List<Order> orders = new ArrayList<>(1000); // Pre-size to avoid resizing
orders.add(new Order("ORD-001", BigDecimal.valueOf(99.99)));
orders.add(new Order("ORD-002", BigDecimal.valueOf(149.99)));

// Binary search on sorted list (O(log n) vs O(n) linear search)
orders.sort(Comparator.comparing(Order::getAmount));
int index = Collections.binarySearch(orders, targetOrder,
    Comparator.comparing(Order::getAmount));

// Sublist view (changes reflect in original list)
List<Order> topOrders = orders.subList(0, Math.min(10, orders.size()));

// Immutable list creation (Java 9+)
List<String> statuses = List.of("PENDING", "PROCESSING", "SHIPPED", "DELIVERED");

// List.copyOf creates immutable copy (Java 10+)
List<Order> snapshot = List.copyOf(orders);

Map Implementations and Patterns // HashMap with computeIfAbsent for lazy initialization
Map<String, List<Order>> ordersByCustomer = new HashMap<>();
for (Order order : allOrders) {
    ordersByCustomer.computeIfAbsent(order.getCustomerId(), k -> new ArrayList<>())
        .add(order);
}

// LinkedHashMap as LRU cache (access-order mode)
Map<String, CachedResponse> cache = new LinkedHashMap<>(16, 0.75f, true) {
    @Override
    protected boolean removeEldestEntry(Map.Entry<String, CachedResponse> eldest) {
        return size() > MAX_CACHE_SIZE;
    }
};

// TreeMap for range queries
TreeMap<LocalDate, List<Transaction>> transactionsByDate = new TreeMap<>();
// Get all transactions in a date range
SortedMap<LocalDate, List<Transaction>> q1Transactions =
    transactionsByDate.subMap(LocalDate.of(2024, 1, 1), LocalDate.of(2024, 4, 1));

// Map.of for small immutable maps (Java 9+)
Map<String, Integer> httpCodes = Map.of(
    "OK", 200,
    "NOT_FOUND", 404,
    "SERVER_ERROR", 500
);

// EnumMap for enum keys (faster than HashMap, uses array internally)
Map<OrderStatus, List<Order>> ordersByStatus = new EnumMap<>(OrderStatus.class);
for (OrderStatus status : OrderStatus.values()) {
    ordersByStatus.put(status, new ArrayList<>());
}

Set Operations and Thread-Safe Collections // HashSet for O(1) membership testing
Set<String> processedIds = new HashSet<>(expectedSize);
for (Event event : events) {
    if (processedIds.add(event.getId())) {
        // First time seeing this event — process it
        processEvent(event);
    }
    // Duplicate — skip silently
}

// TreeSet for sorted unique elements with range operations
TreeSet<Integer> scores = new TreeSet<>(allScores);
int median = scores.stream().skip(scores.size() / 2).findFirst().orElse(0);
SortedSet<Integer> aboveMedian = scores.tailSet(median);

// ConcurrentHashMap for thread-safe operations without external synchronization
ConcurrentHashMap<String, AtomicLong> metrics = new ConcurrentHashMap<>();
// Multiple threads can safely increment counters
metrics.computeIfAbsent("requests", k -> new AtomicLong()).incrementAndGet();
metrics.computeIfAbsent("errors", k -> new AtomicLong()).incrementAndGet();

// CopyOnWriteArrayList for read-heavy, write-rare scenarios
List<EventListener> listeners = new CopyOnWriteArrayList<>();
// Iteration never throws ConcurrentModificationException
for (EventListener listener : listeners) {
    listener.onEvent(event); // Safe even if another thread adds/removes listeners
}

// Collections.unmodifiableMap wraps existing map (view, not copy)
Map<String, Config> configView = Collections.unmodifiableMap(mutableConfig);

ExecutorService and Thread Pools // Fixed thread pool for CPU-bound work
ExecutorService cpuPool = Executors.newFixedThreadPool(
    Runtime.getRuntime().availableProcessors()
);

// Cached thread pool for short-lived I/O tasks
ExecutorService ioPool = Executors.newCachedThreadPool();

// Custom thread pool with bounded queue and rejection policy
ThreadPoolExecutor customPool = new ThreadPoolExecutor(
    4,                          // Core pool size
    16,                         // Maximum pool size
    60L, TimeUnit.SECONDS,      // Keep-alive time for idle threads
    new LinkedBlockingQueue<>(1000),  // Bounded work queue
    new ThreadPoolExecutor.CallerRunsPolicy()  // Backpressure: caller executes task
);

// Submit tasks and collect results
List<Future<ProcessingResult>> futures = orders.stream()
    .map(order -> cpuPool.submit(() -> processOrder(order)))
    .toList();

// Gather results with timeout
List<ProcessingResult> results = new ArrayList<>();
for (Future<ProcessingResult> future : futures) {
    try {
        results.add(future.get(5, TimeUnit.SECONDS));
    } catch (TimeoutException e) {
        future.cancel(true);
        log.warn("Order processing timed out");
    } catch (ExecutionException e) {
        log.error("Order processing failed", e.getCause());
    }
}

// Graceful shutdown
cpuPool.shutdown();
if (!cpuPool.awaitTermination(30, TimeUnit.SECONDS)) {
    cpuPool.shutdownNow();
}

CompletableFuture Composition // Async pipeline with error handling
public CompletableFuture<OrderResult> processOrderAsync(Order order) {
    return CompletableFuture
        .supplyAsync(() -> validateOrder(order), validationPool)
        .thenComposeAsync(validated -> processPayment(validated), paymentPool)
        .thenComposeAsync(paid -> reserveInventory(paid), inventoryPool)
        .thenApplyAsync(reserved -> createShipment(reserved), shippingPool)
        .exceptionally(ex -> {
            log.error("Order processing failed for {}", order.getId(), ex);
            compensate(order);  // Saga compensation
            return OrderResult.failed(order.getId(), ex.getMessage());
        });
}

