public class LoanProcessor {
    public void processLoans(List<Loan> loans) {
        for (Loan loan : loans) {
            // Runtime dispatch to correct calculateEMI implementation
            double emi = loan.calculateEMI();
            System.out.println(loan.getSummary() + " → EMI: " + emi);
        }
    }
}

Interfaces, Sealed Classes, and Records // Sealed interface restricts implementations
public sealed interface Shape permits Circle, Rectangle, Triangle {
    double area();
    double perimeter();
}

// Record provides immutable data carrier
public record Circle(double radius) implements Shape {
    // Compact constructor for validation
    public Circle {
        if (radius <= 0) throw new IllegalArgumentException("Radius must be positive");
    }

    @Override
    public double area() {
        return Math.PI * radius * radius;
    }

    @Override
    public double perimeter() {
        return 2 * Math.PI * radius;
    }
}

public record Rectangle(double width, double height) implements Shape {
    public Rectangle {
        if (width <= 0 || height <= 0)
            throw new IllegalArgumentException("Dimensions must be positive");
    }

    @Override
    public double area() { return width * height; }

    @Override
    public double perimeter() { return 2 * (width + height); }
}

public record Triangle(double a, double b, double c) implements Shape {
    public Triangle {
        if (a + b <= c || a + c <= b || b + c <= a)
            throw new IllegalArgumentException("Invalid triangle sides");
    }

    @Override
    public double area() {
        double s = (a + b + c) / 2;
        return Math.sqrt(s * (s - a) * (s - b) * (s - c));
    }

    @Override
    public double perimeter() { return a + b + c; }
}

// Pattern matching with sealed types (Java 21+)
public String describe(Shape shape) {
    return switch (shape) {
        case Circle c -> "Circle with radius " + c.radius();
        case Rectangle r -> "Rectangle " + r.width() + "x" + r.height();
        case Triangle t -> "Triangle with sides " + t.a() + ", " + t.b() + ", " + t.c();
    };
}

