Trie with Delete Operation Deletion in a trie requires careful cleanup of nodes that are no longer part of any word, using recursive backtracking. public class TrieWithDelete {
    private TrieNode root = new TrieNode();

    public void delete(String word) {
        delete(root, word, 0);
    }

    private boolean delete(TrieNode node, String word, int depth) {
        if (depth == word.length()) {
            if (!node.isEndOfWord) return false;  // Word doesn't exist
            node.isEndOfWord = false;
            return isEmpty(node);  // Can delete node if no children
        }
        int index = word.charAt(depth) - 'a';
        if (node.children[index] == null) return false;

        boolean shouldDeleteChild = delete(node.children[index], word, depth + 1);
        if (shouldDeleteChild) {
            node.children[index] = null;
            return !node.isEndOfWord && isEmpty(node);
        }
        return false;
    }

    private boolean isEmpty(TrieNode node) {
        for (TrieNode child : node.children) {
            if (child != null) return false;
        }
        return true;
    }
}

Autocomplete with Trie (Find All Words with Prefix) Returns all words in the trie that start with a given prefix, useful for search suggestions and typeahead. public List<String> autocomplete(String prefix) {
    List<String> results = new ArrayList<>();
    TrieNode node = root;

    // Navigate to the prefix node
    for (char c : prefix.toCharArray()) {
        int index = c - 'a';
        if (node.children[index] == null) return results;
        node = node.children[index];
    }

    // DFS to find all words from this node
    collectWords(node, new StringBuilder(prefix), results);
    return results;
}

private void collectWords(TrieNode node, StringBuilder current, List<String> results) {
    if (node.isEndOfWord) results.add(current.toString());
    for (int i = 0; i < 26; i++) {
        if (node.children[i] != null) {
            current.append((char)('a' + i));
            collectWords(node.children[i], current, results);
            current.deleteCharAt(current.length() - 1);
        }
    }
}

Word Search with Wildcards Supports '.' as a wildcard matching any single character, commonly used in word games and pattern matching. public boolean searchWithWildcard(String pattern) {
    return searchWildcard(root, pattern, 0);
}

private boolean searchWildcard(TrieNode node, String pattern, int index) {
    if (index == pattern.length()) return node.isEndOfWord;

    char c = pattern.charAt(index);
    if (c == '.') {
        // Try all possible children
        for (int i = 0; i < 26; i++) {
            if (node.children[i] != null &&
                searchWildcard(node.children[i], pattern, index + 1)) {
                return true;
            }
        }
        return false;
    } else {
        int childIndex = c - 'a';
        if (node.children[childIndex] == null) return false;
        return searchWildcard(node.children[childIndex], pattern, index + 1);
    }
}

Binary Search Implementation Binary search is the canonical array algorithm, leveraging sorted order to achieve O(log n) search by repeatedly halving the search space. The implementation requires careful handling of integer overflow and boundary conditions. public class BinarySearch {
    /**
     * Returns the index of target in sorted array, or -1 if not found.
     * Uses overflow-safe midpoint calculation.
     */
    public static int search(int[] arr, int target) {
        int left = 0, right = arr.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;  // Avoids integer overflow
            if (arr[mid] == target) return mid;
            else if (arr[mid] < target) left = mid + 1;
            else right = mid - 1;
        }
        return -1;
    }

    /**
     * Returns the leftmost index where target could be inserted
     * to maintain sorted order (lower bound).
     */
    public static int lowerBound(int[] arr, int target) {
        int left = 0, right = arr.length;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (arr[mid] < target) left = mid + 1;
            else right = mid;
        }
        return left;
    }
} function binarySearch(arr: number[], target: number): number {
  let left = 0;
  let right = arr.length - 1;

  while (left <= right) {
    const mid = left + Math.floor((right - left) / 2);
    if (arr[mid] === target) return mid;
    if (arr[mid] < target) left = mid + 1;
    else right = mid - 1;
  }

  return -1;
}

function lowerBound(arr: number[], target: number): number {
  let left = 0;
  let right = arr.length;

  while (left < right) {
    const mid = left + Math.floor((right - left) / 2);
    if (arr[mid] < target) left = mid + 1;
    else right = mid;
  }

  return left;
}

Dutch National Flag Partition The Dutch National Flag algorithm partitions an array into three sections in a single pass using three pointers. This technique is used in quicksort variants and problems involving categorization of elements. public class DutchNationalFlag {
    /**
     * Partitions array into three regions:
     * [< pivot | == pivot | > pivot]
     * Runs in O(n) time with O(1) extra space.
     */
    public static void partition(int[] arr, int pivot) {
        int low = 0, mid = 0, high = arr.length - 1;

        while (mid <= high) {
            if (arr[mid] < pivot) {
                swap(arr, low++, mid++);
            } else if (arr[mid] == pivot) {
                mid++;
            } else {
                swap(arr, mid, high--);
            }
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
} def dutch_national_flag(arr: list[int], pivot: int) -> None:
    """Partition array in-place into [< pivot, == pivot, > pivot]."""
    low, mid, high = 0, 0, len(arr) - 1

    while mid <= high:
        if arr[mid] < pivot:
            arr[low], arr[mid] = arr[mid], arr[low]
            low += 1
            mid += 1
        elif arr[mid] == pivot:
            mid += 1
        else:
            arr[mid], arr[high] = arr[high], arr[mid]
            high -= 1

Dynamic Array (ArrayList) Internals Understanding how dynamic arrays grow helps predict amortized performance and memory usage in production systems. public class DynamicArray<T> {
    private Object[] data;
    private int size;
    private static final int DEFAULT_CAPACITY = 10;
    private static final double GROWTH_FACTOR = 1.5;

    public DynamicArray() {
        this.data = new Object[DEFAULT_CAPACITY];
        this.size = 0;
    }

    @SuppressWarnings("unchecked")
    public T get(int index) {
        if (index < 0 || index >= size) throw new IndexOutOfBoundsException();
        return (T) data[index];
    }

    public void add(T element) {
        if (size == data.length) {
            resize((int) (data.length * GROWTH_FACTOR) + 1);
        }
        data[size++] = element;
    }

    private void resize(int newCapacity) {
        Object[] newData = new Object[newCapacity];
        System.arraycopy(data, 0, newData, 0, size);
        data = newData;
    }

    public int size() { return size; }
}

Prefix Sum Array for Range Queries The prefix sum array enables O(1) range sum queries after O(n) preprocessing. The key insight is that sum(i, j) equals the cumulative sum up to j minus the cumulative sum up to i-1. public class PrefixSum {
    private final long[] prefix;

    /**
     * Builds prefix sum array from input.
     * prefix[i] = sum of arr[0..i-1], prefix[0] = 0
     * Time: O(n), Space: O(n)
     */
    public PrefixSum(int[] arr) {
        prefix = new long[arr.length + 1];
        for (int i = 0; i < arr.length; i++) {
            prefix[i + 1] = prefix[i] + arr[i];
        }
    }

    /**
     * Returns sum of elements from index left to right (inclusive).
     * Time: O(1)
     */
    public long rangeSum(int left, int right) {
        return prefix[right + 1] - prefix[left];
    }

    /**
     * Count subarrays with sum equal to target.
     * Uses prefix sum + hash map pattern.
     * Time: O(n), Space: O(n)
     */
    public static int subarraySum(int[] nums, int target) {
        Map<Long, Integer> prefixCount = new HashMap<>();
        prefixCount.put(0L, 1);  // Empty prefix has sum 0
        long currentSum = 0;
        int count = 0;

        for (int num : nums) {
            currentSum += num;
            // If (currentSum - target) was a previous prefix sum,
            // then the subarray between them sums to target
            count += prefixCount.getOrDefault(currentSum - target, 0);
            prefixCount.merge(currentSum, 1, Integer::sum);
        }
        return count;
    }
} class PrefixSum {
  private prefix: number[];

  constructor(arr: number[]) {
    this.prefix = new Array(arr.length + 1).fill(0);
    for (let i = 0; i < arr.length; i++) {
      this.prefix[i + 1] = this.prefix[i] + arr[i];
    }
  }

  rangeSum(left: number, right: number): number {
    return this.prefix[right + 1] - this.prefix[left];
  }
}

function subarraySum(nums: number[], target: number): number {
  const prefixCount = new Map<number, number>();
  prefixCount.set(0, 1);
  let currentSum = 0;
  let count = 0;

  for (const num of nums) {
    currentSum += num;
    count += prefixCount.get(currentSum - target) ?? 0;
    prefixCount.set(currentSum, (prefixCount.get(currentSum) ?? 0) + 1);
  }
  return count;
}

2D Prefix Sum (Integral Image) The 2D prefix sum enables O(1) rectangular region sum queries using the inclusion-exclusion principle. This technique is called an "integral image" in computer vision. public class PrefixSum2D {
    private final long[][] prefix;

    /**
     * Builds 2D prefix sum matrix.
     * prefix[i][j] = sum of all elements in matrix[0..i-1][0..j-1]
     * Time: O(rows * cols), Space: O(rows * cols)
     */
    public PrefixSum2D(int[][] matrix) {
        int rows = matrix.length, cols = matrix[0].length;
        prefix = new long[rows + 1][cols + 1];

        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                prefix[i][j] = matrix[i - 1][j - 1]
                    + prefix[i - 1][j]
                    + prefix[i][j - 1]
                    - prefix[i - 1][j - 1];  // Inclusion-exclusion
            }
        }
    }

    /**
     * Sum of elements in rectangle from (r1,c1) to (r2,c2) inclusive.
     * Time: O(1)
     */
    public long regionSum(int r1, int c1, int r2, int c2) {
        return prefix[r2 + 1][c2 + 1]
            - prefix[r1][c2 + 1]
            - prefix[r2 + 1][c1]
            + prefix[r1][c1];
    }
} class PrefixSum2D:
    """2D prefix sum for O(1) rectangular region queries."""

    def __init__(self, matrix: list[list[int]]):
        rows, cols = len(matrix), len(matrix[0])
        self.prefix = [[0] * (cols + 1) for _ in range(rows + 1)]

        for i in range(1, rows + 1):
            for j in range(1, cols + 1):
                self.prefix[i][j] = (
                    matrix[i - 1][j - 1]
                    + self.prefix[i - 1][j]
                    + self.prefix[i][j - 1]
                    - self.prefix[i - 1][j - 1]
                )

    def region_sum(self, r1: int, c1: int, r2: int, c2: int) -> int:
        """Sum of elements in rectangle (r1,c1) to (r2,c2) inclusive."""
        return (
            self.prefix[r2 + 1][c2 + 1]
            - self.prefix[r1][c2 + 1]
            - self.prefix[r2 + 1][c1]
            + self.prefix[r1][c1]
        )

Hash Map Patterns for Array Problems Hash maps enable O(1) complement lookups, frequency counting, and index tracking that transform quadratic algorithms into linear ones. public class HashMapPatterns {
    /**
     * Two Sum: find indices of two numbers that sum to target.
     * Time: O(n), Space: O(n)
     */
    public static int[] twoSum(int[] nums, int target) {
        Map<Integer, Integer> seen = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            int complement = target - nums[i];
            if (seen.containsKey(complement)) {
                return new int[]{seen.get(complement), i};
            }
            seen.put(nums[i], i);
        }
        return new int[]{-1, -1};
    }

    /**
     * Longest subarray with sum equal to k (handles negatives).
     * Stores first occurrence of each prefix sum.
     * Time: O(n), Space: O(n)
     */
    public static int longestSubarrayWithSum(int[] nums, int k) {
        Map<Long, Integer> firstOccurrence = new HashMap<>();
        firstOccurrence.put(0L, -1);  // Empty prefix at index -1
        long sum = 0;
        int maxLen = 0;

        for (int i = 0; i < nums.length; i++) {
            sum += nums[i];
            if (firstOccurrence.containsKey(sum - k)) {
                maxLen = Math.max(maxLen, i - firstOccurrence.get(sum - k));
            }
            firstOccurrence.putIfAbsent(sum, i);  // Only store first occurrence
        }
        return maxLen;
    }

    /**
     * Find majority element (appears more than n/2 times).
     * Boyer-Moore Voting Algorithm: O(n) time, O(1) space.
     */
    public static int majorityElement(int[] nums) {
        int candidate = nums[0], count = 1;
        for (int i = 1; i < nums.length; i++) {
            if (count == 0) {
                candidate = nums[i];
                count = 1;
            } else if (nums[i] == candidate) {
                count++;
            } else {
                count--;
            }
        }
        return candidate;  // Assumes majority element exists
    }
} from collections import defaultdict

def two_sum(nums: list[int], target: int) -> tuple[int, int] | None:
    """Find indices of two numbers summing to target. O(n) time."""
    seen: dict[int, int] = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            return (seen[complement], i)
        seen[num] = i
    return None

def longest_subarray_with_sum(nums: list[int], k: int) -> int:
    """Longest subarray with sum equal to k. Handles negatives."""
    first_occurrence: dict[int, int] = {0: -1}
    current_sum = 0
    max_len = 0

    for i, num in enumerate(nums):
        current_sum += num
        if current_sum - k in first_occurrence:
            max_len = max(max_len, i - first_occurrence[current_sum - k])
        if current_sum not in first_occurrence:
            first_occurrence[current_sum] = i

    return max_len

def group_by_frequency(nums: list[int]) -> dict[int, list[int]]:
    """Group elements by their frequency. O(n) time."""
    freq: dict[int, int] = defaultdict(int)
    for num in nums:
        freq[num] += 1

    groups: dict[int, list[int]] = defaultdict(list)
    for num, count in freq.items():
        groups[count].append(num)
    return dict(groups)

Efficient String Building Demonstrates the performance difference between naive concatenation and StringBuilder, a critical distinction for production code processing large text. public class StringBuilding {
    /**
     * WRONG: O(n^2) due to immutable string concatenation in loop.
     * Each += creates a new String object and copies all previous characters.
     */
    public static String buildNaive(List<String> parts) {
        String result = "";
        for (String part : parts) {
            result += part;  // O(result.length) copy each iteration
        }
        return result;
    }

    /**
     * CORRECT: O(n) total using StringBuilder with pre-sized buffer.
     * Amortized O(1) per append, single toString() at the end.
     */
    public static String buildEfficient(List<String> parts) {
        int totalLength = parts.stream().mapToInt(String::length).sum();
        StringBuilder sb = new StringBuilder(totalLength);  // Pre-allocate
        for (String part : parts) {
            sb.append(part);
        }
        return sb.toString();
    }

    /**
     * String.join() for simple delimiter-based joining.
     * Internally uses StringJoiner which pre-calculates capacity.
     */
    public static String joinWithDelimiter(List<String> parts, String delimiter) {
        return String.join(delimiter, parts);
    }
} // TypeScript string building patterns
