authLogger.warn('Token expiring soon');   // [timestamp] [App:Auth] WARN: Token expiring soon // Memoization using closures for caching expensive computations
function memoize(fn, options = {}) {
  const { maxSize = 100, ttl = null, keyFn = JSON.stringify } = options;
  const cache = new Map();
  const accessOrder = []; // LRU tracking

  function memoized(...args) {
    const key = keyFn(args);

    if (cache.has(key)) {
      const entry = cache.get(key);

      // Check TTL expiration
      if (ttl && Date.now() - entry.timestamp > ttl) {
        cache.delete(key);
      } else {
        // Move to end of access order (most recently used)
        const idx = accessOrder.indexOf(key);
        if (idx > -1) accessOrder.splice(idx, 1);
        accessOrder.push(key);
        return entry.value;
      }
    }

    // Compute and cache
    const value = fn.apply(this, args);

    cache.set(key, { value, timestamp: Date.now() });
    accessOrder.push(key);

    // Evict least recently used if over capacity
    while (cache.size > maxSize) {
      const evictKey = accessOrder.shift();
      cache.delete(evictKey);
    }

    return value;
  }

  // Expose cache management via closure
  memoized.cache = {
    size: () => cache.size,
    clear: () => { cache.clear(); accessOrder.length = 0; },
    has: (args) => cache.has(keyFn(args)),
    delete: (args) => {
      const key = keyFn(args);
      cache.delete(key);
      const idx = accessOrder.indexOf(key);
      if (idx > -1) accessOrder.splice(idx, 1);
    },
  };

  return memoized;
}

