class Range {
  #start;
  #end;
  #step;

  constructor(start, end, step = 1) {
    this.#start = start;
    this.#end = end;
    this.#step = step;
  }

  // Make Range iterable with for...of
  [Symbol.iterator]() {
    let current = this.#start;
    const end = this.#end;
    const step = this.#step;

    return {
      next() {
        if (current <= end) {
          const value = current;
          current += step;
          return { value, done: false };
        }
        return { done: true };
      },
    };
  }

  // Utility methods that leverage iterability
  toArray() {
    return [...this];
  }

  map(fn) {
    return [...this].map(fn);
  }

  filter(fn) {
    return [...this].filter(fn);
  }
}

