Example 1: Responsive Dashboard Layout with CSS Grid /* Modern dashboard layout using Grid with named areas */
.dashboard {
  display: grid;
  grid-template-columns: 250px 1fr 300px;
  grid-template-rows: auto 1fr auto;
  grid-template-areas:
    "header  header  header"
    "sidebar main    aside"
    "footer  footer  footer";
  min-height: 100vh;
  gap: 0;
}

.dashboard__header  { grid-area: header; }
.dashboard__sidebar { grid-area: sidebar; }
.dashboard__main    { grid-area: main; }
.dashboard__aside   { grid-area: aside; }
.dashboard__footer  { grid-area: footer; }

/* Responsive: collapse to single column on mobile */
@media (max-width: 768px) {
  .dashboard {
    grid-template-columns: 1fr;
    grid-template-rows: auto auto 1fr auto auto;
    grid-template-areas:
      "header"
      "main"
      "aside"
      "sidebar"
      "footer";
  }
}

/* Intermediate: two-column layout for tablets */
@media (min-width: 769px) and (max-width: 1024px) {
  .dashboard {
    grid-template-columns: 200px 1fr;
    grid-template-areas:
      "header  header"
      "sidebar main"
      "footer  footer";
  }

  .dashboard__aside {
    grid-area: main;
    /* Aside content flows below main in the same grid area */
  }
} <div class="dashboard">
  <header class="dashboard__header">Navigation</header>
  <nav class="dashboard__sidebar">Sidebar Links</nav>
  <main class="dashboard__main">Primary Content</main>
  <aside class="dashboard__aside">Widgets</aside>
  <footer class="dashboard__footer">Footer</footer>
</div> Grid template areas provide a visual representation of the layout directly in CSS, making it immediately clear how the page is structured. Changing the layout for different breakpoints requires only redefining the template areas rather than restructuring HTML or adding complex positioning rules.

Example 2: Design System Theming with Custom Properties /* Design tokens as custom properties */
:root {
  /* Color palette */
  --color-primary-50: #eff6ff;
  --color-primary-500: #3b82f6;
  --color-primary-700: #1d4ed8;
  --color-primary-900: #1e3a5f;

  /* Semantic tokens (reference palette tokens) */
  --color-bg-primary: #ffffff;
  --color-bg-secondary: #f8fafc;
  --color-text-primary: #0f172a;
  --color-text-secondary: #475569;
  --color-border: #e2e8f0;
  --color-accent: var(--color-primary-500);

  /* Spacing scale */
  --space-xs: 0.25rem;
  --space-sm: 0.5rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;
  --space-2xl: 3rem;

  /* Typography */
  --font-size-sm: clamp(0.8rem, 0.17vw + 0.76rem, 0.89rem);
  --font-size-base: clamp(1rem, 0.34vw + 0.91rem, 1.19rem);
  --font-size-lg: clamp(1.25rem, 0.61vw + 1.1rem, 1.58rem);
  --font-size-xl: clamp(1.56rem, 1vw + 1.31rem, 2.11rem);
  --font-size-2xl: clamp(1.95rem, 1.56vw + 1.56rem, 2.81rem);

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
}

/* Dark theme override — only semantic tokens change */
:root[data-theme="dark"] {
  --color-bg-primary: #0f172a;
  --color-bg-secondary: #1e293b;
  --color-text-primary: #f1f5f9;
  --color-text-secondary: #94a3b8;
  --color-border: #334155;
  --color-accent: var(--color-primary-500);
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.3);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.4);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.4);
}

/* Components consume semantic tokens */
.card {
  background: var(--color-bg-primary);
  border: 1px solid var(--color-border);
  border-radius: var(--space-sm);
  padding: var(--space-lg);
  box-shadow: var(--shadow-sm);
  transition: box-shadow var(--transition-fast);
}

.card:hover {
  box-shadow: var(--shadow-md);
}

.card__title {
  color: var(--color-text-primary);
  font-size: var(--font-size-lg);
  margin-block-end: var(--space-sm);
}

.card__body {
  color: var(--color-text-secondary);
  font-size: var(--font-size-base);
} The two-tier token system (palette tokens and semantic tokens) means theme switching only requires overriding semantic tokens. Components never reference palette colors directly, so adding a new theme (high contrast, brand-specific) requires zero component changes. The clamp() function for typography creates fluid scaling between minimum and maximum sizes without media query breakpoints.

Example 3: Container Queries for Reusable Components /* Define a containment context */
.widget-container {
  container-type: inline-size;
  container-name: widget;
}

/* Component adapts to its container, not the viewport */
.product-card {
  display: grid;
  gap: var(--space-md);
  padding: var(--space-md);
}

/* Narrow container: stack vertically */
@container widget (max-width: 300px) {
  .product-card {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .product-card__image {
    max-width: 150px;
    margin-inline: auto;
  }

  .product-card__actions {
    flex-direction: column;
  }
}

/* Medium container: side-by-side layout */
@container widget (min-width: 301px) and (max-width: 600px) {
  .product-card {
    grid-template-columns: 120px 1fr;
    align-items: start;
  }
}

/* Wide container: full horizontal layout with extra details */
@container widget (min-width: 601px) {
  .product-card {
    grid-template-columns: 200px 1fr auto;
    align-items: center;
  }

  .product-card__details {
    display: block; /* Hidden in narrower containers */
  }
} <!-- Same component, different containers -->
<div class="widget-container" style="width: 250px;">
  <article class="product-card"><!-- Renders stacked --></article>
</div>

<div class="widget-container" style="width: 500px;">
  <article class="product-card"><!-- Renders side-by-side --></article>
</div>

<div class="widget-container" style="width: 800px;">
  <article class="product-card"><!-- Renders full horizontal --></article>
</div> Container queries solve the fundamental limitation of media queries: a component in a narrow sidebar and the same component in wide main content need different layouts, but both exist at the same viewport width. Container queries make components truly self-contained and reusable regardless of where they are placed in the page.

Jenkins Declarative Pipeline // Jenkinsfile - Declarative pipeline
pipeline {
    agent {
        kubernetes {
            yaml '''
                apiVersion: v1
                kind: Pod
                spec:
                  containers:
                  - name: gradle
                    image: gradle:8.4-jdk17
                    command: ['sleep', '99d']
                  - name: docker
                    image: docker:24
                    command: ['sleep', '99d']
                    volumeMounts:
                    - name: docker-sock
                      mountPath: /var/run/docker.sock
                  volumes:
                  - name: docker-sock
                    hostPath:
                      path: /var/run/docker.sock
            '''
        }
    }

    environment {
        DOCKER_REGISTRY = 'registry.example.com'
        IMAGE_NAME = "${DOCKER_REGISTRY}/app:${env.BUILD_NUMBER}"
        GRADLE_OPTS = '-Dorg.gradle.daemon=false'
    }

    options {
        timeout(time: 30, unit: 'MINUTES')
        disableConcurrentBuilds()
        buildDiscarder(logRotator(numToKeepStr: '10'))
    }

    stages {
        stage('Build') {
            steps {
                container('gradle') {
                    sh 'gradle assemble --no-daemon'
                }
            }
        }

        stage('Test') {
            parallel {
                stage('Unit Tests') {
                    steps {
                        container('gradle') {
                            sh 'gradle test --no-daemon'
                        }
                    }
                    post {
                        always {
                            junit 'build/test-results/test/*.xml'
                        }
                    }
                }
                stage('Integration Tests') {
                    steps {
                        container('gradle') {
                            sh 'gradle integrationTest --no-daemon'
                        }
                    }
                }
            }
        }

        stage('Package') {
            steps {
                container('docker') {
                    sh "docker build -t ${IMAGE_NAME} ."
                    sh "docker push ${IMAGE_NAME}"
                }
            }
        }

        stage('Deploy Staging') {
            when {
                branch 'main'
            }
            steps {
                sh "kubectl set image deployment/app app=${IMAGE_NAME} -n staging"
                sh "kubectl rollout status deployment/app -n staging --timeout=300s"
            }
        }

        stage('Deploy Production') {
            when {
                branch 'main'
            }
            input {
                message 'Deploy to production?'
                ok 'Deploy'
                submitter 'admin,release-team'
            }
            steps {
                sh "kubectl set image deployment/app app=${IMAGE_NAME} -n production"
                sh "kubectl rollout status deployment/app -n production --timeout=300s"
            }
        }
    }

    post {
        success {
            slackSend(channel: '#deployments', message: "Build ${env.BUILD_NUMBER} succeeded")
        }
        failure {
            slackSend(channel: '#deployments', color: 'danger',
                      message: "Build ${env.BUILD_NUMBER} failed: ${env.BUILD_URL}")
        }
        always {
            cleanWs()
        }
    }
}

ECS Service with Fargate and Auto Scaling (CDK) import * as cdk from 'aws-cdk-lib';
import * as ecs from 'aws-cdk-lib/aws-ecs';
import * as ec2 from 'aws-cdk-lib/aws-ec2';
import * as elbv2 from 'aws-cdk-lib/aws-elasticloadbalancingv2';
import * as iam from 'aws-cdk-lib/aws-iam';
import * as logs from 'aws-cdk-lib/aws-logs';

export class ComputeStack extends cdk.Stack {
  constructor(scope: cdk.App, id: string, props: ComputeStackProps) {
    super(scope, id, props);

    // ECS Cluster with Container Insights
    const cluster = new ecs.Cluster(this, 'ProductionCluster', {
      vpc: props.vpc,
      clusterName: 'production',
      containerInsights: true,
      enableFargateCapacityProviders: true,
    });

    // Task Definition with appropriate resource allocation
    const taskDef = new ecs.FargateTaskDefinition(this, 'OrderServiceTask', {
      family: 'order-service',
      cpu: 1024,        // 1 vCPU
      memoryLimitMiB: 2048, // 2 GB
      runtimePlatform: {
        cpuArchitecture: ecs.CpuArchitecture.ARM64, // Graviton for cost savings
        operatingSystemFamily: ecs.OperatingSystemFamily.LINUX,
      },
    });

    // Task role with least-privilege permissions
    taskDef.taskRole.addToPrincipalPolicy(new iam.PolicyStatement({
      actions: ['dynamodb:GetItem', 'dynamodb:PutItem', 'dynamodb:Query'],
      resources: [`arn:aws:dynamodb:${this.region}:${this.account}:table/orders`],
    }));

    taskDef.taskRole.addToPrincipalPolicy(new iam.PolicyStatement({
      actions: ['sqs:SendMessage'],
      resources: [`arn:aws:sqs:${this.region}:${this.account}:order-events`],
    }));

    // Container definition with health check and logging
    const container = taskDef.addContainer('order-service', {
      image: ecs.ContainerImage.fromEcrRepository(props.ecrRepo, 'latest'),
      logging: ecs.LogDrivers.awsLogs({
        streamPrefix: 'order-service',
        logGroup: new logs.LogGroup(this, 'OrderServiceLogs', {
          logGroupName: '/ecs/order-service',
          retention: logs.RetentionDays.TWO_WEEKS,
          removalPolicy: cdk.RemovalPolicy.DESTROY,
        }),
      }),
      healthCheck: {
        command: ['CMD-SHELL', 'curl -f http://localhost:8080/actuator/health || exit 1'],
        interval: cdk.Duration.seconds(30),
        timeout: cdk.Duration.seconds(5),
        retries: 3,
        startPeriod: cdk.Duration.seconds(60),
      },
      environment: {
        SPRING_PROFILES_ACTIVE: 'production',
        AWS_REGION: this.region,
      },
      portMappings: [{ containerPort: 8080, protocol: ecs.Protocol.TCP }],
    });

    // ECS Service with deployment circuit breaker
    const service = new ecs.FargateService(this, 'OrderService', {
      cluster,
      taskDefinition: taskDef,
      desiredCount: 3,
      minHealthyPercent: 100,
      maxHealthyPercent: 200,
      circuitBreaker: { rollback: true }, // Auto-rollback failed deployments
      capacityProviderStrategies: [
        { capacityProvider: 'FARGATE', weight: 1, base: 2 },
        { capacityProvider: 'FARGATE_SPOT', weight: 3 }, // 75% Spot for cost savings
      ],
      vpcSubnets: { subnetType: ec2.SubnetType.PRIVATE_WITH_EGRESS },
      securityGroups: [props.appSecurityGroup],
    });

    // Application Auto Scaling
    const scaling = service.autoScaleTaskCount({
      minCapacity: 3,
      maxCapacity: 50,
    });

    scaling.scaleOnCpuUtilization('CpuScaling', {
      targetUtilizationPercent: 60,
      scaleInCooldown: cdk.Duration.seconds(300),
      scaleOutCooldown: cdk.Duration.seconds(60),
    });

    scaling.scaleOnRequestCount('RequestScaling', {
      requestsPerTarget: 1000,
      targetGroup: props.targetGroup,
      scaleInCooldown: cdk.Duration.seconds(300),
      scaleOutCooldown: cdk.Duration.seconds(60),
    });
  }
}

