S3 Bucket with Security Best Practices (CDK) import * as cdk from 'aws-cdk-lib';
import * as s3 from 'aws-cdk-lib/aws-s3';
import * as kms from 'aws-cdk-lib/aws-kms';
import * as iam from 'aws-cdk-lib/aws-iam';

export class SecureStorageStack extends cdk.Stack {
  constructor(scope: cdk.App, id: string, props?: cdk.StackProps) {
    super(scope, id, props);

    // Customer-managed KMS key for encryption
    const encryptionKey = new kms.Key(this, 'DataEncryptionKey', {
      alias: 'production-data-key',
      enableKeyRotation: true,
      removalPolicy: cdk.RemovalPolicy.RETAIN,
      description: 'Encrypts production data in S3',
    });

    // Production data bucket with comprehensive security
    const dataBucket = new s3.Bucket(this, 'ProductionDataBucket', {
      bucketName: `production-data-${this.account}-${this.region}`,
      encryption: s3.BucketEncryption.KMS,
      encryptionKey: encryptionKey,
      bucketKeyEnabled: true, // Reduces KMS API calls by 99%
      versioned: true,
      blockPublicAccess: s3.BlockPublicAccess.BLOCK_ALL,
      enforceSSL: true, // Deny non-HTTPS requests
      minimumTLSVersion: s3.ObjectLockMode.GOVERNANCE,

      // Lifecycle rules for cost optimization
      lifecycleRules: [
        {
          id: 'transition-to-ia',
          transitions: [
            {
              storageClass: s3.StorageClass.INFREQUENT_ACCESS,
              transitionAfter: cdk.Duration.days(30),
            },
            {
              storageClass: s3.StorageClass.GLACIER_INSTANT_RETRIEVAL,
              transitionAfter: cdk.Duration.days(90),
            },
            {
              storageClass: s3.StorageClass.DEEP_ARCHIVE,
              transitionAfter: cdk.Duration.days(365),
            },
          ],
        },
        {
          id: 'cleanup-incomplete-uploads',
          abortIncompleteMultipartUploadAfter: cdk.Duration.days(7),
        },
        {
          id: 'expire-old-versions',
          noncurrentVersionExpiration: cdk.Duration.days(90),
          noncurrentVersionsToRetain: 3,
        },
      ],

      // Access logging for audit trail
      serverAccessLogsBucket: accessLogBucket,
      serverAccessLogsPrefix: 'production-data/',

      // Prevent accidental deletion
      removalPolicy: cdk.RemovalPolicy.RETAIN,
      autoDeleteObjects: false,
    });

    // Bucket policy enforcing encryption and organization access
    dataBucket.addToResourcePolicy(new iam.PolicyStatement({
      sid: 'DenyUnencryptedUploads',
      effect: iam.Effect.DENY,
      principals: [new iam.AnyPrincipal()],
      actions: ['s3:PutObject'],
      resources: [dataBucket.arnForObjects('*')],
      conditions: {
        StringNotEquals: {
          's3:x-amz-server-side-encryption': 'aws:kms',
        },
      },
    }));

    dataBucket.addToResourcePolicy(new iam.PolicyStatement({
      sid: 'RestrictToOrganization',
      effect: iam.Effect.DENY,
      principals: [new iam.AnyPrincipal()],
      actions: ['s3:*'],
      resources: [dataBucket.bucketArn, dataBucket.arnForObjects('*')],
      conditions: {
        StringNotEquals: {
          'aws:PrincipalOrgID': 'o-abc123def4',
        },
      },
    }));
  }
}

Multipart Upload with Retry Logic import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.model.*;
import software.amazon.awssdk.core.sync.RequestBody;

import java.io.File;
import java.io.RandomAccessFile;
import java.util.ArrayList;
import java.util.List;

public class MultipartUploader {
    private static final long PART_SIZE = 100 * 1024 * 1024; // 100MB parts
    private static final int MAX_RETRIES = 3;
    private final S3Client s3Client;

    public MultipartUploader(S3Client s3Client) {
        this.s3Client = s3Client;
    }

    public String uploadLargeFile(String bucket, String key, File file) {
        // Initiate multipart upload
        CreateMultipartUploadResponse initResponse = s3Client.createMultipartUpload(
            CreateMultipartUploadRequest.builder()
                .bucket(bucket)
                .key(key)
                .serverSideEncryption(ServerSideEncryption.AWS_KMS)
                .storageClass(StorageClass.INTELLIGENT_TIERING)
                .metadata(Map.of(
                    "upload-timestamp", Instant.now().toString(),
                    "content-hash", computeSha256(file)
                ))
                .build()
        );

        String uploadId = initResponse.uploadId();
        List<CompletedPart> completedParts = new ArrayList<>();

        try {
            long fileSize = file.length();
            long position = 0;
            int partNumber = 1;

            while (position < fileSize) {
                long partSize = Math.min(PART_SIZE, fileSize - position);
                byte[] partData = readFilePart(file, position, partSize);

                CompletedPart part = uploadPartWithRetry(
                    bucket, key, uploadId, partNumber, partData
                );
                completedParts.add(part);

                position += partSize;
                partNumber++;
            }

            // Complete the multipart upload
            CompleteMultipartUploadResponse response = s3Client.completeMultipartUpload(
                CompleteMultipartUploadRequest.builder()
                    .bucket(bucket)
                    .key(key)
                    .uploadId(uploadId)
                    .multipartUpload(CompletedMultipartUpload.builder()
                        .parts(completedParts)
                        .build())
                    .build()
            );

            return response.eTag();
        } catch (Exception e) {
            // Abort upload on failure to avoid incomplete upload charges
            s3Client.abortMultipartUpload(AbortMultipartUploadRequest.builder()
                .bucket(bucket).key(key).uploadId(uploadId).build());
            throw new RuntimeException("Multipart upload failed", e);
        }
    }

    private CompletedPart uploadPartWithRetry(
            String bucket, String key, String uploadId, int partNumber, byte[] data) {
        for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
            try {
                UploadPartResponse response = s3Client.uploadPart(
                    UploadPartRequest.builder()
                        .bucket(bucket)
                        .key(key)
                        .uploadId(uploadId)
                        .partNumber(partNumber)
                        .build(),
                    RequestBody.fromBytes(data)
                );
                return CompletedPart.builder()
                    .partNumber(partNumber)
                    .eTag(response.eTag())
                    .build();
            } catch (S3Exception e) {
                if (attempt == MAX_RETRIES) throw e;
                Thread.sleep((long) Math.pow(2, attempt) * 1000); // Exponential backoff
            }
        }
        throw new RuntimeException("Unreachable");
    }
}

S3 Event-Driven Processing Pipeline import { S3Event, Context } from 'aws-lambda';
import { S3Client, GetObjectCommand, CopyObjectCommand } from '@aws-sdk/client-s3';
import { SQSClient, SendMessageCommand } from '@aws-sdk/client-sqs';

const s3 = new S3Client({});
const sqs = new SQSClient({});

export async function handler(event: S3Event, context: Context): Promise<void> {
  for (const record of event.Records) {
    const bucket = record.s3.bucket.name;
    const key = decodeURIComponent(record.s3.object.key.replace(/\+/g, ' '));
    const size = record.s3.object.size;

    console.log(JSON.stringify({
      level: 'INFO',
      message: 'Processing S3 event',
      bucket,
      key,
      size,
      eventType: record.eventName,
      requestId: context.awsRequestId,
    }));

    // Validate file before processing
    if (!key.startsWith('uploads/') || size > 500 * 1024 * 1024) {
      console.log(JSON.stringify({ level: 'WARN', message: 'Skipping invalid file', key, size }));
      continue;
    }

    // Move to processing prefix and trigger downstream
    const processingKey = key.replace('uploads/', 'processing/');
    await s3.send(new CopyObjectCommand({
      Bucket: bucket,
      CopySource: `${bucket}/${key}`,
      Key: processingKey,
      ServerSideEncryption: 'aws:kms',
      MetadataDirective: 'COPY',
    }));

    // Send processing message to downstream queue
    await sqs.send(new SendMessageCommand({
      QueueUrl: process.env.PROCESSING_QUEUE_URL,
      MessageBody: JSON.stringify({
        bucket,
        key: processingKey,
        originalKey: key,
        size,
        timestamp: record.eventTime,
      }),
      MessageGroupId: key.split('/')[1], // FIFO ordering by upload prefix
    }));
  }
}

VPC with Multi-AZ Subnets Using AWS CDK import * as cdk from 'aws-cdk-lib';
import * as ec2 from 'aws-cdk-lib/aws-ec2';

export class NetworkingStack extends cdk.Stack {
  public readonly vpc: ec2.Vpc;

  constructor(scope: cdk.App, id: string, props?: cdk.StackProps) {
    super(scope, id, props);

    // Production VPC with carefully planned CIDR
    this.vpc = new ec2.Vpc(this, 'ProductionVpc', {
      vpcName: 'production-vpc',
      ipAddresses: ec2.IpAddresses.cidr('10.0.0.0/16'), // 65,536 IPs
      maxAzs: 3,
      natGateways: 2, // Cost optimization: 2 NATs for 3 AZs

      subnetConfiguration: [
        {
          name: 'Public',
          subnetType: ec2.SubnetType.PUBLIC,
          cidrMask: 24, // 256 IPs per AZ for load balancers, NAT GWs
          mapPublicIpOnLaunch: false, // Explicit control over public IPs
        },
        {
          name: 'Application',
          subnetType: ec2.SubnetType.PRIVATE_WITH_EGRESS,
          cidrMask: 20, // 4,096 IPs per AZ for application workloads
        },
        {
          name: 'Database',
          subnetType: ec2.SubnetType.PRIVATE_ISOLATED,
          cidrMask: 22, // 1,024 IPs per AZ for databases
        },
      ],

      flowLogs: {
        'vpc-flow-logs': {
          destination: ec2.FlowLogDestination.toCloudWatchLogs(),
          trafficType: ec2.FlowLogTrafficType.ALL,
        },
      },
    });

    // VPC Endpoints for AWS service access without NAT Gateway costs
    this.vpc.addGatewayEndpoint('S3Endpoint', {
      service: ec2.GatewayVpcEndpointAwsService.S3,
      subnets: [{ subnetType: ec2.SubnetType.PRIVATE_WITH_EGRESS }],
    });

    this.vpc.addGatewayEndpoint('DynamoDBEndpoint', {
      service: ec2.GatewayVpcEndpointAwsService.DYNAMODB,
    });

    this.vpc.addInterfaceEndpoint('EcrEndpoint', {
      service: ec2.InterfaceVpcEndpointAwsService.ECR,
      privateDnsEnabled: true,
      subnets: { subnetType: ec2.SubnetType.PRIVATE_WITH_EGRESS },
    });

    this.vpc.addInterfaceEndpoint('EcrDockerEndpoint', {
      service: ec2.InterfaceVpcEndpointAwsService.ECR_DOCKER,
      privateDnsEnabled: true,
      subnets: { subnetType: ec2.SubnetType.PRIVATE_WITH_EGRESS },
    });

    this.vpc.addInterfaceEndpoint('CloudWatchLogsEndpoint', {
      service: ec2.InterfaceVpcEndpointAwsService.CLOUDWATCH_LOGS,
      privateDnsEnabled: true,
      subnets: { subnetType: ec2.SubnetType.PRIVATE_WITH_EGRESS },
    });
  }
}

Security Groups with Layered Access Control import * as ec2 from 'aws-cdk-lib/aws-ec2';

// ALB Security Group - accepts traffic from the internet
const albSecurityGroup = new ec2.SecurityGroup(this, 'AlbSg', {
  vpc,
  securityGroupName: 'alb-sg',
  description: 'Security group for Application Load Balancer',
  allowAllOutbound: false,
});
albSecurityGroup.addIngressRule(
  ec2.Peer.anyIpv4(),
  ec2.Port.tcp(443),
  'Allow HTTPS from internet'
);
albSecurityGroup.addEgressRule(
  ec2.Peer.anyIpv4(),
  ec2.Port.tcp(443),
  'Allow outbound HTTPS'
);

// Application Security Group - accepts traffic only from ALB
const appSecurityGroup = new ec2.SecurityGroup(this, 'AppSg', {
  vpc,
  securityGroupName: 'app-sg',
  description: 'Security group for application containers',
  allowAllOutbound: false,
});
appSecurityGroup.addIngressRule(
  albSecurityGroup,
  ec2.Port.tcp(8080),
  'Allow traffic from ALB only'
);
appSecurityGroup.addEgressRule(
  ec2.Peer.anyIpv4(),
  ec2.Port.tcp(443),
  'Allow outbound HTTPS for AWS API calls'
);

// Database Security Group - accepts traffic only from application tier
const dbSecurityGroup = new ec2.SecurityGroup(this, 'DbSg', {
  vpc,
  securityGroupName: 'db-sg',
  description: 'Security group for RDS instances',
  allowAllOutbound: false,
});
dbSecurityGroup.addIngressRule(
  appSecurityGroup,
  ec2.Port.tcp(5432),
  'Allow PostgreSQL from application tier only'
);
// No egress rules - database should not initiate outbound connections

Network ACLs for Subnet-Level Protection // NACL for database subnets - defense in depth beyond security groups
const dbNacl = new ec2.NetworkAcl(this, 'DatabaseNacl', {
  vpc,
  networkAclName: 'database-nacl',
  subnetSelection: { subnetType: ec2.SubnetType.PRIVATE_ISOLATED },
});

// Allow inbound PostgreSQL only from application subnets
dbNacl.addEntry('AllowPostgresInbound', {
  ruleNumber: 100,
  cidr: ec2.AclCidr.ipv4('10.0.16.0/20'), // Application subnet CIDR
  traffic: ec2.AclTraffic.tcpPort(5432),
  direction: ec2.TrafficDirection.INGRESS,
  ruleAction: ec2.Action.ALLOW,
});

// Allow ephemeral port responses back to application subnets
dbNacl.addEntry('AllowEphemeralOutbound', {
  ruleNumber: 100,
  cidr: ec2.AclCidr.ipv4('10.0.16.0/20'),
  traffic: ec2.AclTraffic.tcpPortRange(1024, 65535),
  direction: ec2.TrafficDirection.EGRESS,
  ruleAction: ec2.Action.ALLOW,
});

// Explicit deny all other traffic (NACLs have implicit deny, but explicit is clearer)
dbNacl.addEntry('DenyAllInbound', {
  ruleNumber: 200,
  cidr: ec2.AclCidr.anyIpv4(),
  traffic: ec2.AclTraffic.allTraffic(),
  direction: ec2.TrafficDirection.INGRESS,
  ruleAction: ec2.Action.DENY,
});

Structured Logging and Graceful Shutdown import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.context.event.ContextClosedEvent;
import org.springframework.context.event.EventListener;
import org.springframework.stereotype.Component;

import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

@Component
public class GracefulShutdownHandler {
    private static final Logger log = LoggerFactory.getLogger(GracefulShutdownHandler.class);
    private final AtomicBoolean shuttingDown = new AtomicBoolean(false);

    @EventListener(ContextClosedEvent.class)
    public void onShutdown(ContextClosedEvent event) {
        log.info("Shutdown signal received, beginning graceful termination");
        shuttingDown.set(true);

        // Phase 1: Stop accepting new requests (health check fails)
        log.info("Phase 1: Marked unhealthy, draining in-flight requests");

        // Phase 2: Wait for in-flight requests to complete
        try {
            TimeUnit.SECONDS.sleep(15); // Match k8s terminationGracePeriodSeconds
            log.info("Phase 2: Drain period complete, closing connections");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            log.warn("Drain period interrupted, forcing shutdown");
        }

        // Phase 3: Close database connections and flush buffers
        log.info("Phase 3: Releasing resources and flushing buffers");
    }

    public boolean isShuttingDown() {
        return shuttingDown.get();
    }
}

Alert Configuration with Tiered Severity (CDK) import * as cdk from 'aws-cdk-lib';
import * as cloudwatch from 'aws-cdk-lib/aws-cloudwatch';
import * as sns from 'aws-cdk-lib/aws-sns';
import * as actions from 'aws-cdk-lib/aws-cloudwatch-actions';
import * as chatbot from 'aws-cdk-lib/aws-chatbot';

export class AlertingStack extends cdk.Stack {
  constructor(scope: cdk.App, id: string, props?: cdk.StackProps) {
    super(scope, id, props);

    // Tiered notification channels
    const p1Topic = new sns.Topic(this, 'P1Critical', {
      topicName: 'alerts-p1-critical',
      displayName: 'Critical Alerts - Pages On-Call',
    });

    const p2Topic = new sns.Topic(this, 'P2High', {
      topicName: 'alerts-p2-high',
      displayName: 'High Alerts - Business Hours',
    });

    const p3Topic = new sns.Topic(this, 'P3Medium', {
      topicName: 'alerts-p3-medium',
      displayName: 'Medium Alerts - Ticket Creation',
    });

    // Slack integration for team visibility
    const slackChannel = new chatbot.SlackChannelConfiguration(this, 'AlertsSlack', {
      slackChannelConfigurationName: 'platform-alerts',
      slackWorkspaceId: 'T0123456789',
      slackChannelId: 'C0123456789',
      notificationTopics: [p1Topic, p2Topic],
    });

    // P1: Complete service outage - page immediately
    const serviceDownAlarm = new cloudwatch.Alarm(this, 'ServiceDown', {
      alarmName: 'P1-order-service-down',
      alarmDescription: 'Order service returning zero successful responses. RUNBOOK: https://wiki/runbooks/order-service-down',
      metric: new cloudwatch.Metric({
        namespace: 'OrderService/Production',
        metricName: 'SuccessfulResponses',
        statistic: 'Sum',
        period: cdk.Duration.minutes(1),
      }),
      threshold: 0,
      evaluationPeriods: 3,
      datapointsToAlarm: 3,
      comparisonOperator: cloudwatch.ComparisonOperator.LESS_THAN_OR_EQUAL_TO_THRESHOLD,
      treatMissingData: cloudwatch.TreatMissingData.BREACHING,
    });
    serviceDownAlarm.addAlarmAction(new actions.SnsAction(p1Topic));

    // P2: High error rate - degraded but not down
    const highErrorRate = new cloudwatch.Alarm(this, 'HighErrorRate', {
      alarmName: 'P2-order-service-high-errors',
      alarmDescription: 'Error rate exceeds 5% for sustained period. RUNBOOK: https://wiki/runbooks/high-error-rate',
      metric: new cloudwatch.MathExpression({
        expression: '(errors / total) * 100',
        usingMetrics: {
          errors: new cloudwatch.Metric({
            namespace: 'OrderService/Production',
            metricName: 'Errors',
            statistic: 'Sum',
            period: cdk.Duration.minutes(5),
          }),
          total: new cloudwatch.Metric({
            namespace: 'OrderService/Production',
            metricName: 'TotalRequests',
            statistic: 'Sum',
            period: cdk.Duration.minutes(5),
          }),
        },
      }),
      threshold: 5,
      evaluationPeriods: 3,
      datapointsToAlarm: 2,
      comparisonOperator: cloudwatch.ComparisonOperator.GREATER_THAN_THRESHOLD,
      treatMissingData: cloudwatch.TreatMissingData.NOT_BREACHING,
    });
    highErrorRate.addAlarmAction(new actions.SnsAction(p2Topic));

    // P3: Approaching capacity - needs attention but not urgent
    const highCpuAlarm = new cloudwatch.Alarm(this, 'HighCpu', {
      alarmName: 'P3-order-service-high-cpu',
      alarmDescription: 'CPU utilization approaching limits. Review scaling configuration.',
      metric: new cloudwatch.Metric({
        namespace: 'AWS/ECS',
        metricName: 'CPUUtilization',
        dimensionsMap: { ServiceName: 'order-service', ClusterName: 'production' },
        statistic: 'Average',
        period: cdk.Duration.minutes(10),
      }),
      threshold: 80,
      evaluationPeriods: 6, // 1 hour sustained
      datapointsToAlarm: 5,
      comparisonOperator: cloudwatch.ComparisonOperator.GREATER_THAN_THRESHOLD,
      treatMissingData: cloudwatch.TreatMissingData.NOT_BREACHING,
    });
    highCpuAlarm.addAlarmAction(new actions.SnsAction(p3Topic));

    // Composite alarm: only page for real outages, not transient issues
    const realOutage = new cloudwatch.CompositeAlarm(this, 'RealOutage', {
      compositeAlarmName: 'P1-order-service-confirmed-outage',
      alarmRule: cloudwatch.AlarmRule.allOf(
        cloudwatch.AlarmRule.fromAlarm(serviceDownAlarm, cloudwatch.AlarmState.ALARM),
        cloudwatch.AlarmRule.fromAlarm(highErrorRate, cloudwatch.AlarmState.ALARM)
      ),
    });
    realOutage.addAlarmAction(new actions.SnsAction(p1Topic));
  }
}

Custom Metrics with Embedded Metric Format import { MetricUnit, createMetricsLogger } from 'aws-embedded-metrics';

// Using aws-embedded-metrics library for structured metric emission
export async function processOrder(order: Order): Promise<OrderResult> {
  const metrics = createMetricsLogger();
  metrics.setNamespace('OrderService/Production');
  metrics.setDimensions(
    { ServiceName: 'order-processor', Environment: 'production' },
    { ServiceName: 'order-processor' } // Additional dimension set for aggregation
  );

  const startTime = Date.now();

  try {
    const result = await executeOrderProcessing(order);

    // Emit success metrics
    const duration = Date.now() - startTime;
    metrics.putMetric('ProcessingLatencyMs', duration, MetricUnit.Milliseconds);
    metrics.putMetric('OrdersProcessed', 1, MetricUnit.Count);
    metrics.putMetric('OrderValueCents', order.totalCents, MetricUnit.Count);

    // High-cardinality properties (not dimensions, no cost per unique value)
    metrics.setProperty('orderId', order.id);
    metrics.setProperty('customerId', order.customerId);
    metrics.setProperty('itemCount', order.items.length);

    await metrics.flush();
    return result;
  } catch (error) {
    const duration = Date.now() - startTime;
    metrics.putMetric('ProcessingLatencyMs', duration, MetricUnit.Milliseconds);
    metrics.putMetric('ProcessingErrors', 1, MetricUnit.Count);
    metrics.setProperty('errorType', error.constructor.name);
    metrics.setProperty('errorMessage', error.message);

    await metrics.flush();
    throw error;
  }
}

CloudWatch Alarms with Composite Logic (CDK) import * as cdk from 'aws-cdk-lib';
