    public Backend getBackend() { return backend; }
    public int getWeight() { return weight; }
    public boolean isHealthy() { return healthy; }
}

Consistent Hashing Load Balancer with Virtual Nodes import * as crypto from 'crypto';

interface Backend {
  id: string;
  address: string;
  weight: number;
}

class ConsistentHashBalancer {
  private ring: Map<number, string> = new Map(); // hash -> backendId
  private sortedHashes: number[] = [];
  private backends: Map<string, Backend> = new Map();
  private readonly virtualNodesPerUnit: number;

  constructor(virtualNodesPerUnit: number = 150) {
    this.virtualNodesPerUnit = virtualNodesPerUnit;
  }

  /**
   * Add a backend to the hash ring.
   * Virtual nodes are proportional to weight for weighted distribution.
   */
  addBackend(backend: Backend): void {
    this.backends.set(backend.id, backend);
    const virtualNodes = this.virtualNodesPerUnit * backend.weight;

    for (let i = 0; i < virtualNodes; i++) {
      const hash = this.hash(`${backend.id}:${i}`);
      this.ring.set(hash, backend.id);
    }

    this.rebuildSortedHashes();
  }

  /**
   * Remove a backend from the hash ring.
   * Keys previously routed to this backend will be redistributed
   * to the next backend on the ring (minimal disruption).
   */
  removeBackend(backendId: string): void {
    const backend = this.backends.get(backendId);
    if (!backend) return;

    const virtualNodes = this.virtualNodesPerUnit * backend.weight;
    for (let i = 0; i < virtualNodes; i++) {
      const hash = this.hash(`${backendId}:${i}`);
      this.ring.delete(hash);
    }

    this.backends.delete(backendId);
    this.rebuildSortedHashes();
  }

  /**
   * Route a key to a backend using consistent hashing.
   * The key is hashed and mapped to the next clockwise node on the ring.
   */
  getBackend(key: string): Backend | null {
    if (this.sortedHashes.length === 0) return null;

    const hash = this.hash(key);
    // Binary search for the first hash >= key hash
    let index = this.binarySearchCeil(hash);

    // Wrap around to the first node if past the end
    if (index >= this.sortedHashes.length) {
      index = 0;
    }

    const backendId = this.ring.get(this.sortedHashes[index])!;
    return this.backends.get(backendId) || null;
  }

  /**
   * Get N distinct backends for replication.
   * Walks clockwise from the key's position, skipping duplicate backends.
   */
  getBackends(key: string, count: number): Backend[] {
    if (this.sortedHashes.length === 0) return [];

    const hash = this.hash(key);
    let index = this.binarySearchCeil(hash);
    const result: Backend[] = [];
    const seen = new Set<string>();

    for (let i = 0; i < this.sortedHashes.length && result.length < count; i++) {
      const wrappedIndex = (index + i) % this.sortedHashes.length;
      const backendId = this.ring.get(this.sortedHashes[wrappedIndex])!;

      if (!seen.has(backendId)) {
        seen.add(backendId);
        const backend = this.backends.get(backendId);
        if (backend) result.push(backend);
      }
    }

    return result;
  }

  private hash(key: string): number {
    const md5 = crypto.createHash('md5').update(key).digest();
    return md5.readUInt32BE(0);
  }

  private binarySearchCeil(target: number): number {
    let low = 0;
    let high = this.sortedHashes.length - 1;

    while (low <= high) {
      const mid = Math.floor((low + high) / 2);
      if (this.sortedHashes[mid] < target) {
        low = mid + 1;
      } else {
        high = mid - 1;
      }
    }
    return low;
  }

  private rebuildSortedHashes(): void {
    this.sortedHashes = Array.from(this.ring.keys()).sort((a, b) => a - b);
  }

  getStats(): { backendId: string; keyCount: number; percentage: number }[] {
    const counts = new Map<string, number>();
    // Sample 10000 random keys to estimate distribution
    for (let i = 0; i < 10000; i++) {
      const backend = this.getBackend(`sample-key-${i}`);
      if (backend) {
        counts.set(backend.id, (counts.get(backend.id) || 0) + 1);
      }
    }
    return Array.from(counts.entries()).map(([id, count]) => ({
      backendId: id,
      keyCount: count,
      percentage: (count / 10000) * 100
    }));
  }
}

Health Check System with Circuit Breaking public class HealthChecker {
    private final ScheduledExecutorService scheduler;
    private final Map<String, BackendHealth> healthStates = new ConcurrentHashMap<>();
    private final HealthCheckConfig config;
    private final LoadBalancer loadBalancer;

    public HealthChecker(LoadBalancer loadBalancer, HealthCheckConfig config) {
        this.loadBalancer = loadBalancer;
        this.config = config;
        this.scheduler = Executors.newScheduledThreadPool(4);
    }

    public void startMonitoring(List<Backend> backends) {
        for (Backend backend : backends) {
            healthStates.put(backend.getId(), new BackendHealth(backend));
            scheduler.scheduleAtFixedRate(
                () -> checkHealth(backend),
                0,
                config.getCheckInterval().toMillis(),
                TimeUnit.MILLISECONDS
            );
        }
    }

    private void checkHealth(Backend backend) {
        BackendHealth health = healthStates.get(backend.getId());

        try {
            HttpResponse response = sendHealthProbe(backend);
            long latency = response.getLatencyMs();

            if (response.getStatusCode() == 200 && latency < config.getLatencyThreshold()) {
                health.recordSuccess(latency);
                if (!health.isHealthy() && health.getConsecutiveSuccesses()
                        >= config.getHealthyThreshold()) {
                    // Backend recovered: add back to rotation
                    health.markHealthy();
                    loadBalancer.addBackend(backend);
                    logEvent("Backend recovered", backend, health);
                }
            } else {
                health.recordFailure(response.getStatusCode(), latency);
                handleFailure(backend, health);
            }
        } catch (Exception e) {
            health.recordFailure(-1, -1);
            handleFailure(backend, health);
        }
    }

    private void handleFailure(Backend backend, BackendHealth health) {
        if (health.isHealthy() && health.getConsecutiveFailures()
                >= config.getUnhealthyThreshold()) {
            // Backend failed: remove from rotation
            health.markUnhealthy();
            loadBalancer.removeBackend(backend);
            logEvent("Backend removed", backend, health);
        }
    }

    private HttpResponse sendHealthProbe(Backend backend) {
        // Send HTTP GET to backend's health endpoint with timeout
        String url = backend.getAddress() + config.getHealthPath();
        return httpClient.get(url)
            .timeout(config.getProbeTimeout())
            .execute();
    }

    public Map<String, BackendHealthStatus> getHealthReport() {
        Map<String, BackendHealthStatus> report = new LinkedHashMap<>();
        for (Map.Entry<String, BackendHealth> entry : healthStates.entrySet()) {
            BackendHealth health = entry.getValue();
            report.put(entry.getKey(), new BackendHealthStatus(
                health.isHealthy(),
                health.getAverageLatency(),
                health.getSuccessRate(),
                health.getLastCheckTime(),
                health.getConsecutiveFailures()
            ));
        }
        return report;
    }
}

class BackendHealth {
    private final Backend backend;
    private volatile boolean healthy = true;
    private final AtomicInteger consecutiveSuccesses = new AtomicInteger(0);
    private final AtomicInteger consecutiveFailures = new AtomicInteger(0);
    private final SlidingWindowCounter successCounter;
    private final SlidingWindowCounter totalCounter;
    private final MovingAverage latencyAverage;
    private volatile Instant lastCheckTime;

    public BackendHealth(Backend backend) {
        this.backend = backend;
        this.successCounter = new SlidingWindowCounter(Duration.ofMinutes(5));
        this.totalCounter = new SlidingWindowCounter(Duration.ofMinutes(5));
        this.latencyAverage = new MovingAverage(100); // Last 100 samples
    }

    public void recordSuccess(long latencyMs) {
        consecutiveSuccesses.incrementAndGet();
        consecutiveFailures.set(0);
        successCounter.increment();
        totalCounter.increment();
        latencyAverage.add(latencyMs);
        lastCheckTime = Instant.now();
    }

    public void recordFailure(int statusCode, long latencyMs) {
        consecutiveFailures.incrementAndGet();
        consecutiveSuccesses.set(0);
        totalCounter.increment();
        if (latencyMs > 0) latencyAverage.add(latencyMs);
        lastCheckTime = Instant.now();
    }

    public double getSuccessRate() {
        long total = totalCounter.getCount();
        return total == 0 ? 1.0 : (double) successCounter.getCount() / total;
    }

    public void markHealthy() { this.healthy = true; }
    public void markUnhealthy() { this.healthy = false; }
    public boolean isHealthy() { return healthy; }
    public int getConsecutiveSuccesses() { return consecutiveSuccesses.get(); }
    public int getConsecutiveFailures() { return consecutiveFailures.get(); }
    public double getAverageLatency() { return latencyAverage.getAverage(); }
    public Instant getLastCheckTime() { return lastCheckTime; }
}

Auto-Scaling Decision Engine public class AutoScaler {
    private final MetricsClient metricsClient;
    private final InstanceManager instanceManager;
    private final ScalingPolicy policy;
    private Instant lastScaleAction = Instant.EPOCH;

    public AutoScaler(MetricsClient metricsClient, InstanceManager instanceManager,
                      ScalingPolicy policy) {
        this.metricsClient = metricsClient;
        this.instanceManager = instanceManager;
        this.policy = policy;
    }

    /**
     * Evaluate scaling decision based on current metrics.
     * Implements cooldown period to prevent thrashing.
     */
    public ScalingDecision evaluate() {
        // Respect cooldown period
        Duration sinceLastAction = Duration.between(lastScaleAction, Instant.now());
        if (sinceLastAction.compareTo(policy.getCooldownPeriod()) < 0) {
            return ScalingDecision.noAction("Cooldown period active");
        }

        int currentInstances = instanceManager.getActiveInstanceCount();
        AggregatedMetrics metrics = metricsClient.getAggregatedMetrics(
            policy.getMetricWindow()
        );

        // Scale-out decision: based on leading indicators
        if (shouldScaleOut(metrics, currentInstances)) {
            int targetInstances = calculateScaleOutTarget(metrics, currentInstances);
            targetInstances = Math.min(targetInstances, policy.getMaxInstances());
            lastScaleAction = Instant.now();
            return ScalingDecision.scaleOut(targetInstances - currentInstances);
        }

        // Scale-in decision: more conservative, uses trailing indicators
        if (shouldScaleIn(metrics, currentInstances)) {
            int targetInstances = calculateScaleInTarget(metrics, currentInstances);
            targetInstances = Math.max(targetInstances, policy.getMinInstances());
            lastScaleAction = Instant.now();
            return ScalingDecision.scaleIn(currentInstances - targetInstances);
        }

        return ScalingDecision.noAction("Metrics within acceptable range");
    }

    private boolean shouldScaleOut(AggregatedMetrics metrics, int currentInstances) {
        return metrics.getAvgCpuUtilization() > policy.getScaleOutCpuThreshold()
            || metrics.getP99Latency() > policy.getScaleOutLatencyThreshold()
            || metrics.getQueueDepth() > policy.getScaleOutQueueThreshold();
    }

    private boolean shouldScaleIn(AggregatedMetrics metrics, int currentInstances) {
        return currentInstances > policy.getMinInstances()
            && metrics.getAvgCpuUtilization() < policy.getScaleInCpuThreshold()
            && metrics.getP99Latency() < policy.getScaleInLatencyThreshold()
            && metrics.getQueueDepth() < policy.getScaleInQueueThreshold();
    }

    private int calculateScaleOutTarget(AggregatedMetrics metrics, int current) {
        // Target: bring CPU utilization to 60% (leaving headroom for spikes)
        double targetUtilization = 0.6;
        double currentLoad = metrics.getAvgCpuUtilization() * current;
        return (int) Math.ceil(currentLoad / targetUtilization);
    }

    private int calculateScaleInTarget(AggregatedMetrics metrics, int current) {
        // Conservative: remove at most 25% of instances per scale-in event
        int maxRemoval = Math.max(1, current / 4);
        double targetUtilization = 0.7;
        double currentLoad = metrics.getAvgCpuUtilization() * current;
        int target = (int) Math.ceil(currentLoad / targetUtilization);
        return Math.max(target, current - maxRemoval);
    }
}

Connection Pool with Health Checking interface PoolConfig {
  minConnections: number;
  maxConnections: number;
  acquireTimeout: number;      // ms to wait for available connection
  idleTimeout: number;         // ms before idle connection is closed
  healthCheckInterval: number; // ms between health checks
  maxLifetime: number;         // ms before connection is recycled
}

class ConnectionPool {
  private available: Connection[] = [];
  private inUse: Set<Connection> = new Set();
  private waitQueue: Array<{
    resolve: (conn: Connection) => void;
    reject: (err: Error) => void;
    timer: NodeJS.Timeout;
  }> = [];
  private config: PoolConfig;
  private healthCheckTimer: NodeJS.Timeout | null = null;

  constructor(config: PoolConfig) {
    this.config = config;
    this.initialize();
  }

  private async initialize(): Promise<void> {
    // Pre-warm minimum connections
    for (let i = 0; i < this.config.minConnections; i++) {
      const conn = await this.createConnection();
      this.available.push(conn);
    }
    // Start periodic health checks
    this.healthCheckTimer = setInterval(
      () => this.healthCheck(),
      this.config.healthCheckInterval
    );
  }

  async acquire(): Promise<Connection> {
    // Try to get an available connection
    while (this.available.length > 0) {
      const conn = this.available.pop()!;
      if (this.isHealthy(conn) && !this.isExpired(conn)) {
        this.inUse.add(conn);
        return conn;
      }
      // Connection is unhealthy or expired, discard it
      conn.destroy();
    }

    // Create new connection if under max limit
    const totalConnections = this.inUse.size + this.available.length;
    if (totalConnections < this.config.maxConnections) {
      const conn = await this.createConnection();
      this.inUse.add(conn);
      return conn;
    }

    // All connections in use and at max: wait in queue
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        const index = this.waitQueue.findIndex(w => w.resolve === resolve);
        if (index !== -1) this.waitQueue.splice(index, 1);
        reject(new Error(
          `Connection acquire timeout after ${this.config.acquireTimeout}ms. ` +
          `Pool: ${this.inUse.size} active, ${this.available.length} idle, ` +
          `${this.waitQueue.length} waiting`
        ));
      }, this.config.acquireTimeout);

      this.waitQueue.push({ resolve, reject, timer });
    });
  }

  release(conn: Connection): void {
    this.inUse.delete(conn);

    // If waiters exist, give connection directly to next waiter
    if (this.waitQueue.length > 0) {
      const waiter = this.waitQueue.shift()!;
      clearTimeout(waiter.timer);
      this.inUse.add(conn);
      waiter.resolve(conn);
      return;
    }

    // Return to available pool if healthy
    if (this.isHealthy(conn) && !this.isExpired(conn)) {
      conn.lastUsed = Date.now();
      this.available.push(conn);
    } else {
      conn.destroy();
    }

    // Maintain minimum pool size
    this.replenishPool();
  }

  private async healthCheck(): Promise<void> {
    const now = Date.now();
    const toRemove: Connection[] = [];

    for (const conn of this.available) {
      // Remove idle connections beyond minimum
      if (now - conn.lastUsed > this.config.idleTimeout
          && this.available.length > this.config.minConnections) {
        toRemove.push(conn);
      }
      // Remove expired connections
      else if (this.isExpired(conn)) {
        toRemove.push(conn);
      }
    }

    for (const conn of toRemove) {
      const index = this.available.indexOf(conn);
      if (index !== -1) this.available.splice(index, 1);
      conn.destroy();
    }

    await this.replenishPool();
  }

  private isExpired(conn: Connection): boolean {
    return Date.now() - conn.createdAt > this.config.maxLifetime;
  }

  private isHealthy(conn: Connection): boolean {
    return conn.isConnected && !conn.hasError;
  }

  private async replenishPool(): Promise<void> {
    const total = this.inUse.size + this.available.length;
    const deficit = this.config.minConnections - total;
    for (let i = 0; i < deficit; i++) {
      try {
        const conn = await this.createConnection();
        this.available.push(conn);
      } catch {
        break; // Stop trying if connection creation fails
      }
    }
  }

  private async createConnection(): Promise<Connection> {
    // Implementation depends on the database driver
    const conn = await Connection.create();
    conn.createdAt = Date.now();
    conn.lastUsed = Date.now();
    return conn;
  }

  getStats(): PoolStats {
    return {
      active: this.inUse.size,
      idle: this.available.length,
      waiting: this.waitQueue.length,
      total: this.inUse.size + this.available.length
    };
  }
}

Stateless Service Design with External Session Store /**
 * Demonstrates stateless service design where all session state
 * is externalized to Redis, allowing any instance to handle any request.
 */
@RestController
public class OrderController {
    private final RedisTemplate<String, CartState> sessionStore;
    private final OrderService orderService;
    private final String instanceId;

    public OrderController(RedisTemplate<String, CartState> sessionStore,
                           OrderService orderService) {
        this.sessionStore = sessionStore;
        this.orderService = orderService;
        this.instanceId = UUID.randomUUID().toString().substring(0, 8);
    }

    @PostMapping("/cart/{sessionId}/items")
    public ResponseEntity<CartState> addItem(
            @PathVariable String sessionId,
            @RequestBody AddItemRequest request) {

        // Load state from external store (any instance can serve this)
        String key = "cart:" + sessionId;
        CartState cart = sessionStore.opsForValue().get(key);
        if (cart == null) {
            cart = new CartState(sessionId);
        }

        // Apply business logic
        cart.addItem(request.getProductId(), request.getQuantity(), request.getPrice());
        cart.setLastModified(Instant.now());
        cart.setLastServedBy(instanceId); // For debugging routing

        // Persist state back to external store
        sessionStore.opsForValue().set(key, cart, Duration.ofHours(24));

        return ResponseEntity.ok(cart);
    }

    @PostMapping("/cart/{sessionId}/checkout")
    public ResponseEntity<OrderConfirmation> checkout(@PathVariable String sessionId) {
        String key = "cart:" + sessionId;
        CartState cart = sessionStore.opsForValue().get(key);

        if (cart == null || cart.getItems().isEmpty()) {
            return ResponseEntity.badRequest().build();
        }

        // Process order (idempotent via order ID)
        OrderConfirmation confirmation = orderService.placeOrder(cart);

        // Clear cart state after successful checkout
        sessionStore.delete(key);

        return ResponseEntity.ok(confirmation);
    }

    @GetMapping("/health/ready")
    public ResponseEntity<Map<String, Object>> readiness() {
        // Readiness depends on external dependencies being available
        boolean redisHealthy = checkRedisConnection();
        boolean dbHealthy = checkDatabaseConnection();

        Map<String, Object> status = Map.of(
            "instance", instanceId,
            "redis", redisHealthy,
            "database", dbHealthy,
            "ready", redisHealthy && dbHealthy
        );

        return (redisHealthy && dbHealthy)
            ? ResponseEntity.ok(status)
            : ResponseEntity.status(503).body(status);
    }
}

Two Pointers Pattern — Container With Most Water /**
 * Find two lines that together with the x-axis form a container
 * that holds the most water. O(n) time, O(1) space.
 *
 * Key insight: Start with widest container, move the shorter line
 * inward because moving the taller line can only decrease area.
 */
public class ContainerWithMostWater {

    public int maxArea(int[] height) {
        int left = 0;
        int right = height.length - 1;
        int maxWater = 0;

        while (left < right) {
            int width = right - left;
            int minHeight = Math.min(height[left], height[right]);
            int currentArea = width * minHeight;
            maxWater = Math.max(maxWater, currentArea);

            // Move the pointer at the shorter line inward
            // Moving the taller line cannot increase area since
            // width decreases and height is bounded by the shorter line
            if (height[left] < height[right]) {
                left++;
            } else {
                right--;
            }
        }

        return maxWater;
    }

    // Interview follow-up: What if we need to return the indices?
    public int[] maxAreaWithIndices(int[] height) {
        int left = 0, right = height.length - 1;
        int maxWater = 0;
        int[] result = new int[2];

        while (left < right) {
            int area = (right - left) * Math.min(height[left], height[right]);
            if (area > maxWater) {
                maxWater = area;
                result[0] = left;
                result[1] = right;
            }
            if (height[left] < height[right]) left++;
            else right--;
        }
        return result;
    }
}

Sliding Window Pattern — Longest Substring Without Repeating Characters /**
 * Find the length of the longest substring without repeating characters.
 * O(n) time, O(min(m,n)) space where m is charset size.
 *
 * Key insight: Maintain a window [left, right] where all characters are unique.
 * When a duplicate is found, shrink from the left until the window is valid again.
 */
function lengthOfLongestSubstring(s: string): number {
  const charIndex = new Map<string, number>();
  let maxLength = 0;
  let left = 0;

  for (let right = 0; right < s.length; right++) {
    const char = s[right];

    // If character was seen and its last position is within current window,
    // move left pointer past the previous occurrence
    if (charIndex.has(char) && charIndex.get(char)! >= left) {
      left = charIndex.get(char)! + 1;
    }

    charIndex.set(char, right);
    maxLength = Math.max(maxLength, right - left + 1);
  }

  return maxLength;
}

// Interview discussion points:
// 1. Why Map over Set? Map stores position, enabling O(1) left pointer jump
// 2. Why check >= left? Characters outside window are irrelevant
// 3. Space complexity: O(min(26, n)) for lowercase English, O(min(128, n)) for ASCII

/**
 * Follow-up: Find the actual longest substring, not just its length.
 */
function longestSubstringWithoutRepeats(s: string): string {
  const charIndex = new Map<string, number>();
  let maxLength = 0;
  let maxStart = 0;
  let left = 0;

  for (let right = 0; right < s.length; right++) {
    const char = s[right];
    if (charIndex.has(char) && charIndex.get(char)! >= left) {
      left = charIndex.get(char)! + 1;
    }
    charIndex.set(char, right);

    if (right - left + 1 > maxLength) {
      maxLength = right - left + 1;
      maxStart = left;
    }
  }

  return s.substring(maxStart, maxStart + maxLength);
}

Dynamic Programming Pattern — Longest Increasing Subsequence /**
 * Find the length of the longest strictly increasing subsequence.
 * Two approaches shown: O(n^2) DP and O(n log n) patience sorting.
 *
 * Interview strategy: Start with O(n^2) DP, then optimize if time permits.
 */
public class LongestIncreasingSubsequence {

    // Approach 1: Classic DP — O(n^2) time, O(n) space
    // dp[i] = length of LIS ending at index i
    public int lengthOfLIS_DP(int[] nums) {
        int n = nums.length;
        int[] dp = new int[n];
        Arrays.fill(dp, 1); // every element is a subsequence of length 1

        int maxLength = 1;

        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (nums[j] < nums[i]) {
                    dp[i] = Math.max(dp[i], dp[j] + 1);
                }
            }
            maxLength = Math.max(maxLength, dp[i]);
        }

        return maxLength;
    }

    // Approach 2: Patience Sorting — O(n log n) time, O(n) space
    // Maintain sorted tails array; binary search for insertion point
    public int lengthOfLIS_Optimized(int[] nums) {
        // tails[i] = smallest tail element for increasing subsequence of length i+1
        List<Integer> tails = new ArrayList<>();

        for (int num : nums) {
            int pos = Collections.binarySearch(tails, num);

            // binarySearch returns -(insertion point) - 1 if not found
            if (pos < 0) pos = -(pos + 1);

            if (pos == tails.size()) {
                tails.add(num); // extend longest subsequence
            } else {
                tails.set(pos, num); // replace to maintain smallest tail
            }
        }

        return tails.size();
    }

    // Interview follow-up: Reconstruct the actual subsequence
    public List<Integer> actualLIS(int[] nums) {
        int n = nums.length;
        int[] dp = new int[n];
        int[] parent = new int[n];
        Arrays.fill(dp, 1);
        Arrays.fill(parent, -1);

        int maxLength = 1, maxIndex = 0;

        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (nums[j] < nums[i] && dp[j] + 1 > dp[i]) {
                    dp[i] = dp[j] + 1;
                    parent[i] = j;
                }
            }
            if (dp[i] > maxLength) {
                maxLength = dp[i];
                maxIndex = i;
            }
        }

        // Reconstruct path
        List<Integer> result = new ArrayList<>();
        int idx = maxIndex;
        while (idx != -1) {
            result.add(0, nums[idx]);
            idx = parent[idx];
        }
        return result;
    }
}

Negotiation Decision Tree /**
 * Decision framework for responding to offers and counter-offers.
 * Models the negotiation state machine with recommended actions.
 */

interface NegotiationState {
  hasOffer: boolean;
  hasCompetingOffer: boolean;
  offerExpirationDays: number;
  currentOfferTotal: number;
  targetTotal: number;
  negotiationRound: number;
  maxRounds: number;
}

interface NegotiationAction {
  action: string;
  script: string;
  reasoning: string;
  riskLevel: "low" | "medium" | "high";
}

function getNextAction(state: NegotiationState): NegotiationAction {
  // Rule 1: Never accept immediately — always take time to evaluate
  if (state.negotiationRound === 0) {
    return {
      action: "express_enthusiasm_and_delay",
      script:
        "Thank you so much for this offer — I'm genuinely excited about " +
        "the role and the team. I'd like to take a few days to review the " +
        "full package carefully. Could I get back to you by [date]?",
      reasoning:
        "Taking time signals professionalism, not disinterest. " +
        "It also creates space to gather competing offers.",
      riskLevel: "low",
    };
  }

  // Rule 2: If below target and have competing offer, leverage it
  if (
    state.currentOfferTotal < state.targetTotal &&
    state.hasCompetingOffer
  ) {
    return {
      action: "leverage_competing_offer",
      script:
        "I'm very excited about this opportunity and your team is my " +
        "top choice. I do have a competing offer at [X total comp]. " +
        "Is there flexibility to close the gap? I'd love to make this work.",
      reasoning:
        "Competing offers provide objective market data. " +
        "Framing as 'help me choose you' is collaborative, not adversarial.",
      riskLevel: "low",
    };
  }

  // Rule 3: If below target without competing offer, negotiate on merit
  if (
    state.currentOfferTotal < state.targetTotal &&
    !state.hasCompetingOffer
  ) {
    return {
      action: "negotiate_on_value",
      script:
        "Based on my research and the scope of this role, I was " +
        "targeting [X] in total compensation. Given my experience with " +
        "[specific relevant skill] and the impact I expect to have on " +
        "[specific team goal], is there room to adjust the package?",
      reasoning:
        "Without competing offers, anchor on market data and " +
        "unique value you bring. Be specific about what justifies the ask.",
      riskLevel: "medium",
    };
  }

  // Rule 4: If at or above target, negotiate non-monetary terms
  if (state.currentOfferTotal >= state.targetTotal) {
    return {
      action: "optimize_non_monetary",
      script:
        "The compensation is strong and I appreciate the team working " +
        "with me on this. A few things that would make this perfect: " +
        "[remote flexibility / signing bonus timing / start date / " +
        "title adjustment / equity refresh guarantee]. Are any of these " +
        "possible?",
      reasoning:
        "Once monetary comp is satisfactory, optimize for " +
        "quality of life and career positioning factors.",
      riskLevel: "low",
    };
  }

  // Rule 5: Final round — accept or walk away
  return {
    action: "make_final_decision",
    script:
      "I've really enjoyed this process and I'm ready to make a " +
      "decision. [Accept: I'd love to join the team.] " +
      "[Decline: After careful consideration, I've decided to pursue " +
      "another opportunity that better aligns with my goals right now.]",
    reasoning:
      "After 2-3 rounds, further pushing risks the offer. " +
      "Make a clear decision and communicate it professionally.",
    riskLevel: "low",
  };
}

Explaining Complex Concepts — Layered Approach /**
 * Technical communication pattern: Explain at multiple levels of abstraction.
 * Start with the "what and why", then progressively add "how" details.
 *
 * Example: Explaining consistent hashing to different audiences.
 */

// Level 1: Executive summary (30 seconds)
const executiveSummary = `
  Consistent hashing lets us add or remove servers without redistributing
  all data. When a server fails, only 1/N of the data moves instead of
  reshuffling everything. This means faster recovery and less customer impact
  during scaling events.
`;

// Level 2: Technical overview (2 minutes)
const technicalOverview = `
  Traditional hash(key) % N breaks when N changes — every key gets a new
  assignment. Consistent hashing maps both keys and servers onto a ring
  (0 to 2^32). Each key is assigned to the next server clockwise on the ring.
  Adding a server only affects keys between it and its predecessor.
  Virtual nodes (multiple positions per server) ensure even distribution.
`;

// Level 3: Implementation details (5+ minutes)
interface ConsistentHashRing<T> {
  addNode(node: T, virtualNodes?: number): void;
  removeNode(node: T): void;
  getNode(key: string): T;
  getReplicationNodes(key: string, count: number): T[];
}

class ConsistentHash<T> implements ConsistentHashRing<T> {
  private ring: Map<number, T> = new Map();
  private sortedKeys: number[] = [];
  private virtualNodeCount: number;

  constructor(virtualNodes: number = 150) {
    this.virtualNodeCount = virtualNodes;
  }

  addNode(node: T): void {
    for (let i = 0; i < this.virtualNodeCount; i++) {
      const hash = this.hash(`${node}-vn${i}`);
      this.ring.set(hash, node);
      this.sortedKeys.push(hash);
    }
    this.sortedKeys.sort((a, b) => a - b);
  }

  removeNode(node: T): void {
    for (let i = 0; i < this.virtualNodeCount; i++) {
      const hash = this.hash(`${node}-vn${i}`);
      this.ring.delete(hash);
      this.sortedKeys = this.sortedKeys.filter(k => k !== hash);
    }
  }

  getNode(key: string): T {
    const hash = this.hash(key);
    // Find first node clockwise from the key's position
    const idx = this.findCeiling(hash);
    const nodeHash = this.sortedKeys[idx % this.sortedKeys.length];
    return this.ring.get(nodeHash)!;
  }

  getReplicationNodes(key: string, count: number): T[] {
    const nodes: Set<T> = new Set();
    const hash = this.hash(key);
    let idx = this.findCeiling(hash);

    while (nodes.size < count && nodes.size < this.ring.size) {
      const node = this.ring.get(this.sortedKeys[idx % this.sortedKeys.length])!;
      nodes.add(node);
      idx++;
    }
    return Array.from(nodes);
  }

  private hash(key: string): number {
    // Simplified hash — production would use MurmurHash3 or xxHash
    let hash = 0;
    for (let i = 0; i < key.length; i++) {
      hash = ((hash << 5) - hash + key.charCodeAt(i)) | 0;
    }
    return Math.abs(hash);
  }

  private findCeiling(hash: number): number {
    let lo = 0, hi = this.sortedKeys.length - 1;
    while (lo < hi) {
      const mid = (lo + hi) >>> 1;
      if (this.sortedKeys[mid] < hash) lo = mid + 1;
      else hi = mid;
    }
    return lo;
  }
}
